        'intro' => 'ஒரே தயாரிப்பாளர் பெரும்பாலும் பல எழுத்துக்கூட்டல்களில் வருகிறார் - HP, HP Inc., Hewlett-Packard - இது வரைபடங்களையும் வடிகட்டிகளையும் பிரிக்கிறது. அதற்குப் பதிலாகக் காட்ட வேண்டிய பெயரைத் தேர்ந்தெடுக்கவும். காட்டப்படுவது மட்டுமே மாறும்: ஒவ்வொரு சொத்தும் அறிக்கையிடப்பட்ட அல்லது தட்டச்சு செய்தவற்றையே வைத்திருக்கும், எனவே இங்கே ஒரு வரியை நீக்கினால் அது செயல்தவிர்க்கப்படும்.',
