        'intro' => 'இரண்டு பதிவுகள் ஒன்றாக இருக்கக்கூடும் என்றபோதும், அல்லது ஒரு கருவி பொருத்த முடியாத சாதனத்தை அறிக்கையிடும்போதும் FreeITSM ஒருபோதும் ஊகிப்பதில்லை. அத்தகைய நிகழ்வுகள் நீங்கள் முடிவு செய்ய இங்கே காத்திருக்கும். தானாகவே தீர்ந்துவிடும் நிகழ்வைத் தவிர, இங்கே எதுவும் தானாக மாறாது.',
