        'kind_hostname_reused' => '{o} இன்னும் வைத்திருக்கும் பெயருடன் {a} கண்டறியப்பட்டது, ஆனால் வரிசை எண் வேறு - பொதுவாக இது மாற்று இயந்திரம். இது அதே இயந்திரம் என்றால் (எ.கா. புதிய மதர்போர்டு), அவற்றை இணைக்கவும்.',
        'kind_unmatched' => '{source} {what} (வரிசை எண் {serial}) {host} உடன் இணைக்கப்பட்டுள்ளதாக அறிக்கையிட்டது, ஆனால் அந்த வரிசை எண் கொண்ட சொத்து எதுவும் இல்லை.',
        'kind_ambiguous' => '{source} வரிசை எண் {serial} {host} உடன் இணைக்கப்பட்டுள்ளதாக அறிக்கையிட்டது, ஆனால் அந்த வரிசை எண் ஒன்றுக்கு மேற்பட்ட சொத்துகளுக்கு உள்ளது. முதலில் ஒரே வரிசை எண் என்பதன் கீழ் அவற்றில் எது என்பதை முடிவு செய்யவும்.',
