        'merge_title' => 'இரண்டு சொத்துகளை இணை',
        'merge_intro' => 'வைத்திருக்க வேண்டிய பதிவைத் தேர்ந்தெடுக்கவும். மற்றதில் உள்ள அனைத்தும் இதற்கு மாறும்: வரலாறு, டிக்கெட்டுகள், ஒப்பந்தங்கள், ஆவணங்கள், திட்டங்கள், குத்தகைகள், பொறுப்பு, இணைப்புகள், தனிப்பயன் புல மதிப்புகள் மற்றும் inventory.',
        'merge_hint' => 'இரண்டிலும் மதிப்பு இருந்தால், நீங்கள் வைத்திருப்பதன் மதிப்பே நிற்கும், காலியான புலம் மற்றதிலிருந்து நிரப்பப்படும். பின்னர் மற்றப் பதிவு அகற்றப்படும் - அதன் QR லேபிள் இதையே கண்டுபிடிக்கும், REST API வழியாக அதற்கு அறிக்கையிடும் கருவிகளும் அவ்வாறே. இதை மீட்க முடியாது.',
        'merge_confirm' => '{gone} ஐ {keep} உடன் இணைக்கவா? {gone} அகற்றப்பட்டு, அதில் உள்ள அனைத்தும் {keep} க்கு மாற்றப்படும். இதை மீட்க முடியாது.',
        'keep_this' => 'இதை வைத்திரு',
