        'ci_both_heading' => 'இரண்டு சொத்துகளும் ஒரு கட்டமைப்பு உருப்படியுடன் இணைக்கப்பட்டுள்ளன',
        'ci_both_intro' => 'ஒரு சொத்தை ஒரு கட்டமைப்பு உருப்படியுடன் மட்டுமே இணைக்க முடியும். வைத்திருக்க வேண்டிய இணைப்பைத் தேர்ந்தெடுக்கவும். மற்றது முடிவடைந்து இணைப்பு வரலாற்றில் இருக்கும். எந்தக் கட்டமைப்பு உருப்படியும், அதன் உறவுகளும் மாறாது.',
