        'tab_asset_types' => 'சொத்து வகைகள்',
        'tab_asset_statuses' => 'சொத்து நிலைகள்',
        'asset_types_intro' => 'சொத்துகளை நீங்கள் வகைப்படுத்தும் பிரிவுகள் &mdash; லேப்டாப், டெஸ்க்டாப், சர்வர், மானிட்டர், போன் மற்றும் பல. ஒவ்வொரு சொத்துக்கும் ஒரு வகை வழங்கப்படும்; அதுவே பட்டியல் எவ்வாறு குழுவாக்கப்பட்டு வடிகட்டப்படுகிறது என்பதைத் தீர்மானிக்கிறது.',
        'asset_statuses_intro' => 'ஒரு சொத்து இருக்கக்கூடிய வாழ்க்கைச் சுழற்சி நிலைகள் &mdash; எடுத்துக்காட்டாக பயன்பாட்டில், இருப்பில், பழுதுபார்ப்பில் அல்லது ஓய்வு. ஒவ்வொரு சொத்தும் ஒரு நிலைக்கு அமைக்கப்படுவதால், அது தன் வாழ்க்கையில் எங்கு உள்ளது என்பதை ஒரே பார்வையில் காணலாம்.',
        'type_icon' => 'ஐகான்',
        'type_icon_none' => 'ஐகான் இல்லை',
        'type_icon_hint' => 'இந்த வகையின் ஒவ்வொரு சொத்தின் அருகிலும் காட்டப்படும், இதனால் உபகரணப் பட்டியலை ஒரே பார்வையில் படிக்கலாம். கட்டமைப்பு உருப்படிகளுக்கும் இதே ஐகான் தொகுப்பு பயன்படுத்தப்படுவதால், பிரிண்டர் எல்லா இடங்களிலும் பிரிண்டர் போலவே தெரியும்.',
