        'type_cmdb_class_hint' => 'இந்த வகைச் சொத்துகள் இணைக்கப்பட்ட CI உருவாக்கு என்பதை வழங்கும், இது இந்த வகுப்பின் கட்டமைப்பு உருப்படியை உருவாக்கி இணைக்கும். ஒரு வகுப்பைத் தேர்ந்தெடுப்பது தானாக எதையும் உருவாக்காது, இருக்கும் சொத்துகளில் எதையும் மாற்றாது.',
