        'tab_suppliers' => 'வழங்குநர்கள்',
        'tab_import' => 'இறக்குமதி',
        'imp_intro' => 'ஒரு விரிதாளிலிருந்து சொத்துகளைக் கொண்டுவாருங்கள் &mdash; சப்ளையரிடமிருந்து வந்த இருப்புப் பட்டியல், வேறு அமைப்பிலிருந்து ஏற்றுமதி செய்த கோப்பு, அல்லது யாரோ பராமரித்து வரும் எதுவானாலும். நெடுவரிசைகளை ஒருமுறை இணைத்தால், அதே கோப்பு புதுப்பிக்கப்படும்போதெல்லாம் எல்லாவற்றையும் இரண்டாவது முறை உருவாக்காமல் மீண்டும் இறக்குமதி செய்யலாம்.',
        'imp_not_ready' => 'இறக்குமதிக்கு முதலில் தரவுத்தளப் புதுப்பிப்பு தேவை. <strong>கணினி &rarr; தரவுத்தள சரிபார்ப்பு</strong> என்பதற்குச் சென்று அதை இயக்கிவிட்டு, பின்னர் திரும்பி வாருங்கள்.',
        'imp_step_file' => '1. கோப்பு',
        'imp_step_file_intro' => 'தலைப்பு வரிசையுடன் கூடிய CSV. ஒரு விரிதாள் சேமிக்கக்கூடிய எதுவும் ஏற்கப்படும்.',
        'imp_read' => 'படி',
        'imp_pick_file' => 'முதலில் ஒரு கோப்பைத் தேர்ந்தெடுக்கவும்.',
        'imp_file_read' => '<strong>{file}</strong> படிக்கப்பட்டது &mdash; {rows} வரிசை(கள்), {cols} நெடுவரிசை(கள்).',
        'imp_truncated' => 'முதல் {max} வரிசைகள் மட்டுமே இறக்குமதி செய்யப்படும் &mdash; மீதமுள்ளவற்றுக்கு கோப்பைப் பிரித்து மீண்டும் இயக்கவும்.',
        'imp_step_map' => '2. ஒவ்வொரு நெடுவரிசையும் எங்கு செல்கிறது',
        'imp_step_map_intro' => 'உங்கள் கோப்பிலிருந்து முதல் சில மதிப்புகள் ஒவ்வொரு நெடுவரிசையின் அருகிலும் காட்டப்படுகின்றன, இதனால் தவறான ஊகம் எந்தச் சேதமும் செய்யும் முன்பே தெரிந்துவிடும். <em>இறக்குமதி செய்யாதே</em> என விடப்பட்டவை முழுமையாகப் புறக்கணிக்கப்படும்.',
        'imp_col_source' => 'உங்கள் கோப்பில் உள்ள நெடுவரிசை',
        'imp_col_sample' => 'முதல் சில மதிப்புகள்',
        'imp_col_target' => 'செல்லும் இடம்',
        'imp_ignore' => 'இறக்குமதி செய்யாதே',
        'imp_group_core' => 'உள்ளமைந்த விவரங்கள்',
        'imp_group_fields' => 'தனிப்பயன் புலங்கள்',
        'imp_ignored' => '{n} நெடுவரிசை(கள்) புறக்கணிக்கப்படும்:',
        'imp_step_match' => '3. ஒரு வரிசையை எது அடையாளப்படுத்துகிறது',
        'imp_step_match_intro' => '<strong>முக்கியமானது இந்த அமைப்புதான்.</strong> உங்கள் கோப்பில் உள்ள வரிசை புதிய சொத்தா அல்லது ஏற்கனவே உள்ள ஒன்றா என்பதை FreeITSM இதன் மூலமே தீர்மானிக்கிறது. ஒரு உபகரணத்துக்கு மட்டுமே உரிய நெடுவரிசைகளை, அவை சரிபார்க்கப்பட வேண்டிய வரிசையில் தேர்வுசெய்யவும். இது தவறினால், அடுத்த மாதம் அதே கோப்பை இறக்குமதி செய்யும்போது எல்லாம் இரண்டாவது முறை உருவாக்கப்படும். ஒரு வரிசை <em>ஒன்றுக்கு மேற்பட்ட</em> ஏற்கனவே உள்ள சொத்துகளுடன் பொருந்தினால் எதுவும் மாற்றப்படாது; அந்த வரிசை நீங்கள் பார்ப்பதற்காக ஒதுக்கி வைக்கப்படும் &mdash; அங்கே ஊகிப்பதால்தான் பதிவுகள் அமைதியாக மேலெழுதப்படுகின்றன.',
        'imp_need_match' => 'ஒரு வரிசையை அடையாளப்படுத்தும் குறைந்தது ஒரு நெடுவரிசையைத் தேர்வுசெய்யவும்.',
        'imp_write_mode' => 'ஒரு சொத்தில் ஏற்கனவே மதிப்பு இருக்கும்போது',
        'imp_write_fill' => 'அதைத் தொடாமல் விடு, வெறுமையானவற்றை மட்டும் நிரப்பு',
        'imp_write_overwrite' => 'கோப்பின் மதிப்பைக் கொண்டு மாற்று',
        'imp_unknown_option' => 'ஒரு புலத்தின் தேர்வுப் பட்டியலில் இல்லாத மதிப்பு',
        'imp_unknown_reject' => 'வரிசையை ஒதுக்கி வை',
        'imp_unknown_add' => 'தேர்வுகளில் சேர்',
        'imp_default_type' => 'குறிப்பிடாத வரிசைகளுக்கான சொத்து வகை',
        'imp_step_go' => '4. சரிபார், பின்னர் இறக்குமதி செய்',
        'imp_step_go_intro' => 'முன்னோட்டம் ஒவ்வொரு சரிபார்ப்பையும் செய்கிறது, ஆனால் எதையும் எழுதாது. உண்மையான இயக்கம் என்ன செய்யும் என்பதை வரிசை வரிசையாகத் துல்லியமாகக் காட்டுகிறது.',
        'imp_preview' => 'முன்னோட்டம்',
        'imp_go' => 'இறக்குமதி',
        'imp_preview_first' => 'முதலில் முன்னோட்டம் பாருங்கள் &mdash; அது என்ன செய்யும் என்பதைப் பார்த்த பிறகே இறக்குமதி பொத்தான் செயல்படும்.',
        'imp_preview_heading' => 'முன்னோட்டம் மட்டுமே &mdash; எதுவும் எழுதப்படவில்லை.',
        'imp_live_heading' => 'இறக்குமதி செய்யப்பட்டது.',
        'imp_done' => 'இறக்குமதி முடிந்தது.',
        'imp_failed' => 'அது வேலை செய்யவில்லை.',
        'imp_no_rows' => 'வரிசைகள் இல்லை.',
        'imp_row_n' => 'வரிசை {n}',
        'imp_act_create' => 'புதியது',
        'imp_act_update' => 'புதுப்பிக்கப்பட்டது',
        'imp_act_unchanged' => 'மாற்றம் இல்லை',
        'imp_act_conflict' => 'தெளிவற்றது',
        'imp_act_skip' => 'தவிர்க்கப்பட்டது',
        'imp_act_error' => 'சிக்கல்',
        'imp_act_deactivate' => 'நீங்கியது',
        'imp_held' => 'கவனம் தேவைப்படும் வரிசைகள்',
        'imp_held_intro' => 'இறக்குமதி செய்ய முடியாத வரிசைகள், தூக்கி எறியப்படாமலும் ஊகிக்கப்படாமலும், உங்கள் கோப்பில் உண்மையில் இருந்தவற்றுடன் இங்கே வைக்கப்படுகின்றன. விரிதாளைச் சரிசெய்து மீண்டும் இறக்குமதி செய்யுங்கள், அல்லது விடுபட்டதை உருவாக்கி மீண்டும் இயக்குங்கள் &mdash; பின்னர் அந்த வரிசையை இந்தப் பட்டியலிலிருந்து நீக்க முடிந்தது எனக் குறியுங்கள்.',
        'imp_held_count' => '{n} காத்திருக்கின்றன',
        'imp_held_none' => 'எதுவும் காத்திருக்கவில்லை',
        'imp_held_empty' => 'எதற்கும் கவனம் தேவையில்லை.',
        'imp_resolve' => 'முடிந்தது',
        'imp_history' => 'கடந்த இறக்குமதிகள்',
        'imp_no_runs' => 'இதுவரை எதுவும் இறக்குமதி செய்யப்படவில்லை.',
        'imp_col_when' => 'எப்போது',
        'imp_col_file' => 'கோப்பு',
        'imp_col_result' => 'முடிவு',
        'imp_col_who' => 'இயக்கியவர்',
        'imp_run_summary' => '{created} புதியவை, {updated} புதுப்பிக்கப்பட்டவை, {unchanged} மாற்றமில்லாதவை, {problems} கவனம் தேவைப்படுபவை',
        'tab_custom_fields' => 'தனிப்பயன் புலங்கள்',
        'cf_intro' => 'உள்ளமைந்த சொத்து விவரங்கள் ஒரு கணினியை விவரிக்கின்றன, ஏனெனில் இன்வென்டரி ஏஜென்ட் அதையே தெரிவிக்கிறது. மற்ற எல்லாவற்றையும் &mdash; பிரிண்டர்கள், மானிட்டர்கள், ஹெட்செட்கள், தொலைக்காட்சிகள் &mdash; உங்களுக்கு முக்கியமான விவரங்களுடன் பதிவு செய்யும் வழி தனிப்பயன் புலங்களே. ஒன்றைச் சேர்த்தால் உடனே நடைமுறைக்கு வரும்: தரவுத்தள மாற்றம் தேவையில்லை, ஏற்கனவே பதிவானவை எதுவும் தொடப்படாது.',
        'cf_not_ready' => 'தனிப்பயன் புலங்களுக்கு முதலில் தரவுத்தளப் புதுப்பிப்பு தேவை. <strong>கணினி &rarr; தரவுத்தள சரிபார்ப்பு</strong> என்பதற்குச் சென்று அதை இயக்கிவிட்டு, பின்னர் திரும்பி வாருங்கள்.',
        'cf_tree' => 'அனைத்தும் எப்படி இணைகிறது',
        'cf_tree_intro' => 'ஒவ்வொரு சொத்து வகையும், அதனுடன் இணைக்கப்பட்ட தொகுப்புகளும், அவற்றில் உள்ள புலங்களும். ஒரு புலம் பல வகைகளின் கீழ் தோன்றலாம் &mdash; அது இன்னும் ஒரே புலம்தான், அதனால்தான் அவை அனைத்திலும் ஒரே நேரத்தில் தேட முடிகிறது. இங்கே எதையும் மாற்ற முடியாது; நீங்கள் அமைத்தவற்றின் ஒரு படம் மட்டுமே இது.',
        'cf_tree_hide' => 'மறை',
        'cf_tree_show' => 'காட்டு',
        'cf_tree_set_of' => '{n} புலம்(ங்கள்)',
        'cf_tree_set_empty' => 'இந்தத் தொகுப்பில் இன்னும் புலங்கள் எதுவும் இல்லை.',
        'cf_tree_type_none' => 'கூடுதலாக எதுவும் பதிவு செய்யப்படவில்லை',
        'cf_tree_bare' => '{n} சொத்து வகை(கள்) கூடுதலாக எதையும் பதிவு செய்வதில்லை',
        'cf_tree_no_types' => 'இன்னும் சொத்து வகைகள் இல்லை.',
        'cf_tree_where' => 'ஒவ்வொரு புலமும் எங்கு பயன்படுத்தப்படுகிறது',
        'cf_tree_field_unused' => 'எந்தத் தொகுப்பிலும் இல்லை, எனவே இதுவரை எதுவும் இதைப் பதிவு செய்யவில்லை',
        'cf_tree_set_unused' => 'எந்தச் சொத்து வகையுடனும் இணைக்கப்படாத ஒரு தொகுப்பில் உள்ளது',
        'cf_sec_types' => 'சொத்து வகை வாரியாகப் புலங்கள்',
        'cf_sec_types_intro' => 'ஒரு சொத்து வகையைத் தேர்ந்தெடுத்து, அதற்கு எதைப் பதிவு செய்வது என்பதைத் தேர்வுசெய்யவும். அந்த வகையின் அனைத்தும் உடனே அந்தப் புலங்களைப் பெறும்.',
        'cf_sec_catalogue' => 'அனைத்துப் புலங்கள்',
        'cf_sec_catalogue_intro' => 'நீங்கள் வரையறுத்த ஒவ்வொரு புலமும். ஒரு புலம் <strong>ஒருமுறை</strong> வரையறுக்கப்பட்டு, நீங்கள் விரும்பும் பல சொத்து வகைகளால் பயன்படுத்தப்படலாம் &mdash; எனவே ஹெட்செட்டில் உள்ள &ldquo;வரிசை எண்&rdquo; தொலைக்காட்சியில் உள்ள அதே புலம்தான், ஒரே தேடலில் இரண்டும் கிடைக்கும்.',
        'cf_sec_sets' => 'புலத் தொகுப்புகள்',
        'cf_sec_sets_intro' => 'தொகுப்பு என்பது ஒரு வகையுடன் ஒரே நேரத்தில் இணைக்கும் புலங்களின் கட்டு &mdash; பல வகைகளுக்கு ஒரே சில புலங்கள் தேவைப்படும்போது பயனுள்ளது. தொகுப்பில் &ldquo;வாங்கிய இடம்&rdquo; என்பதைச் சேர்த்தால், அதைப் பயன்படுத்தும் ஒவ்வொரு வகையும் அந்தப் புலத்தை ஒரே நேரத்தில் பெறும்.',
