        'cf_field_in_list' => 'சொத்துப் பட்டியலில் நெடுவரிசையாக வழங்கு',
        'cf_field_searchable' => 'இந்தப் புலம் மூலம் சொத்துகளைக் கண்டுபிடி',
        'cf_field_searchable_hint' => 'தேடல் பெட்டியில் (அல்லது &#8984;K) ஒரு மதிப்பை உள்ளிட்டால், அதனுடன் பதிவான சொத்துகள் கிடைக்கும். யாராவது உண்மையில் தேடக்கூடியவற்றுக்கு &mdash; வரிசை எண் அல்லது தெளிவுத்திறன் போன்றவற்றுக்கு &mdash; ஏற்றது; தனி உரைக் குறிப்புக்கு அல்ல.',
