        'cf_type_locked' => 'இந்தப் புலத்தில் ஏற்கனவே {n} மதிப்பு(கள்) பதிவாகியுள்ளதால், தகவல் வகையை இனி மாற்ற முடியாது. அது தவறாக இருந்தால் இதை நீக்கிவிட்டு புதியதைச் சேர்க்கவும்.',
        'cf_builtin_warn' => 'ஒவ்வொரு சொத்திலும் ஏற்கனவே உள்ளமைந்த <strong>{field}</strong> உள்ளது. இதைத் தனிப்பயன் புலமாகச் சேர்த்தால், சேர் உரையாடல் இரண்டு முறை கேட்கும், மேலும் எந்த அறிக்கையும் இரண்டையும் இணைக்க முடியாது. இரண்டாவது தேவை என்று குறிப்பாக விரும்பினால் தவிர, உள்ளமைந்ததையே பயன்படுத்தவும்.',
        'cf_used_by' => '{n} தொகுப்பு(கள்) பயன்படுத்துகின்றன',
