        'locations_intro' => 'உங்கள் நிறுவனத்திற்கு ஏற்ற இட படிநிலையை உருவாக்கவும் &mdash; விரும்பும் அளவுக்கு ஆழமாகவோ அல்லது மேலோட்டமாகவோ அதை அடுக்கவும், ஒவ்வொரு கிளையும் வேறுபடலாம். உதாரணமாக <code>UK &rsaquo; London &rsaquo; Office 1</code> மற்றும் ஒரு எளிய <code>Datacentre</code>. துணை இடத்தைச் சேர்க்க எந்த இடத்திலும் <strong>+</strong> ஐப் பயன்படுத்தவும்.',
        'locations_system_note' => 'இந்த இடங்கள் FreeITSM முழுவதும் பயன்படுத்தப்படுகின்றன, சொத்துகளில் மட்டுமல்ல - படிவங்களும் ஒன்றைக் கேட்கலாம். நிர்வாகிகள் இதே பட்டியலை <strong>கணினி &rarr; இடங்கள்</strong> என்பதிலும் காணலாம்; எந்த இடத்தில் மாற்றினாலும் இரண்டிலும் தெரியும்.',
