        'location_shared' => 'ஒவ்வொரு நிறுவனத்துடனும் பகிரப்பட்டது',
        'location_shared_hint' => 'பல வாடிக்கையாளர்கள் பயன்படுத்தும் டேட்டா சென்டர் போன்ற பகிரப்பட்ட இடத்தை ஒவ்வொரு நிறுவனமும் தேர்ந்தெடுக்கலாம். ஒவ்வொரு நிறுவனத்துக்கும் அணுகல் உள்ளவர் மட்டுமே இதை மாற்ற முடியும்.',
        'location_shared_badge' => 'பகிரப்பட்டது',
