        'save_location_failed' => 'இடத்தைச் சேமிக்க முடியவில்லை',
        'suppliers_intro' => 'ஒரு சொத்தில் தேர்ந்தெடுக்கக்கூடிய வழங்குநர்களைத் தேர்வு செய்யவும். இவை பகிரப்பட்ட வழங்குநர் பதிவேட்டிலிருந்து வருகின்றன (ஒப்பந்தங்களாலும் பயன்படுத்தப்படுகிறது), எனவே ஒரு வன்பொருள் விற்பனையாளரும் ஒப்பந்த வழங்குநரும் ஒரே பதிவாகும். நீங்கள் வன்பொருள் வாங்குபவர்களில் <strong>சொத்துகளுக்கு கிடைக்கும்</strong> ஐ இயக்கவும். பட்டியலில் இல்லாத ஒன்று தேவையா? பெயர் மூலம் சேர்க்கவும் &mdash; முழு விவரங்களை பின்னர் ஒப்பந்தங்களில் நிரப்பலாம்.',
        'supplier_search_placeholder' => 'வழங்குநர்களைத் தேடு...',
        'supplier_new_placeholder' => 'புதிய வழங்குநர் பெயர்',
        'col_supplier' => 'வழங்குநர்',
