        'no_suppliers' => 'பதிவேட்டில் இன்னும் வழங்குநர்கள் இல்லை. மேலே பெயர் மூலம் ஒன்றைச் சேர்க்கவும்.',
        'no_supplier_match' => 'உங்கள் தேடலுக்கு பொருந்தும் வழங்குநர்கள் இல்லை.',
        'supplier_enabled' => 'சொத்துகளுக்கு கிடைக்கும்',
