        'supplier_added' => 'வழங்குநர் சேர்க்கப்பட்டார்',
        'add_supplier_failed' => 'வழங்குநரைச் சேர்க்க முடியவில்லை',
        'warranty_heading' => 'உத்தரவாத காலாவதி எச்சரிக்கைகள்',
        'warranty_intro' => 'ஒவ்வொரு சொத்தின் <strong>உத்தரவாத காலாவதி</strong> தேதியின் அடிப்படையில், உத்தரவாதம் காலாவதியான அல்லது காலாவதியாகப் போகும் சொத்துகளை வெளிப்படுத்துங்கள். அவை எங்கே காண்பிக்கப்படும் என்பதைத் தேர்வு செய்யவும் &mdash; Watchtower டாஷ்போர்டில் ஒரு கார்டு, காலெண்டரில் நிகழ்வுகள் ("Warranty" வகையில்), அல்லது இரண்டும்.',
