        'warranty_days_label' => 'காலாவதிக்கு இத்தனை நாட்களுக்கு முன் எச்சரிக்கவும்',
        'warranty_days_hint' => 'உத்தரவாத தேதியை ஏற்கனவே கடந்த சொத்துகள் எப்போதும் சேர்க்கப்படுகின்றன.',
        'warranty_saved' => 'உத்தரவாத எச்சரிக்கை அமைப்புகள் சேமிக்கப்பட்டன',
        'lease_heading' => 'குத்தகை காலாவதி எச்சரிக்கைகள்',
        'lease_intro' => 'ஒவ்வொரு சொத்தின் <strong>குத்தகை முடிவு</strong> தேதியின் அடிப்படையில், குத்தகை முடிந்த அல்லது முடியவிருக்கும் சொத்துகளை முன்னிலைப்படுத்தவும். அவை எங்கு தோன்ற வேண்டும் என்பதைத் தேர்வுசெய்யவும் &mdash; Watchtower டாஷ்போர்டில் ஒரு அட்டை, நாட்காட்டியில் ("குத்தகை" வகையில்) நிகழ்வுகள், அல்லது இரண்டும்.',
        'lease_show_in' => 'குத்தகை காலாவதிகளைக் காட்டும் இடம்',
        'lease_days_label' => 'இத்தனை நாட்கள் முன்னதாக எச்சரி',
        'lease_days_hint' => 'குத்தகை முடிவு தேதியைக் கடந்த சொத்துகள் எப்போதும் சேர்க்கப்படும். உத்தரவாத எச்சரிக்கையை விட நீண்ட கால அவகாசம் வழக்கம்: குத்தகை உபகரணத்தைத் திருப்பி அனுப்ப அல்லது புதுப்பிக்க ஏற்பாடு தேவை.',
        'lease_saved' => 'குத்தகை எச்சரிக்கை அமைப்புகள் சேமிக்கப்பட்டன',
