        'password_saved_placeholder' => 'சேமிக்கப்பட்டது (மாற்ற புதிய கடவுச்சொல்லை உள்ளிடவும்)',
        'show' => 'காட்டு',
        'hide' => 'மறை',
        'settings_saved' => 'அமைப்புகள் வெற்றிகரமாக சேமிக்கப்பட்டன',
        'intune_heading' => 'Microsoft InTune ஒருங்கிணைப்பு',
        'intune_intro' => 'நிர்வகிக்கப்பட்ட சாதன சரக்கை இறக்குமதி செய்ய Azure AD ஆப் பதிவைப் பயன்படுத்தி Microsoft Graph வழியாக Microsoft InTune உடன் இணைக்கவும்.',
        'intune_tenant_id' => 'Tenant ID',
