        'intune_secret_placeholder' => 'Client secret ஐ உள்ளிடவும்',
        'intune_secret_hint' => 'சேமித்த secret ஐ வைத்திருக்க மாற்றாமல் விடவும்',
        'secret_saved_placeholder' => 'சேமிக்கப்பட்டது (மாற்ற புதிய secret ஐ உள்ளிடவும்)',
        'verify_ssl' => 'SSL ஐ சரிபார்',
        'verify_ssl_hint' => 'சுய-கையொப்பமிட்ட சான்றிதழ்கள் கொண்ட சூழல்களுக்கு எதிராக சோதனை செய்ய மட்டுமே முடக்கவும்',
        'verify_ssl_warning' => '<strong>எச்சரிக்கை:</strong> SSL சரிபார்ப்பு அணைக்கப்பட்டுள்ளது. FreeITSM, Microsoft இன் சேவையகங்களிலிருந்து எந்த TLS சான்றிதழையும் சரிபார்க்காமல் ஏற்கும். உங்கள் நெட்வொர்க்கிற்கு (அல்லது உங்கள் DNS, அல்லது சமரசம் செய்யப்பட்ட சான்றிதழ் ஆணையம்) அணுகல் உள்ள எவரும் Microsoft ஆகப் பாசாங்கு செய்து, போக்குவரத்தை இடைமறித்து, உங்கள் tenant ID, client ID, client secret மற்றும் தொடரும் அணுகல் டோக்கன்களைத் திருடலாம். சுய-கையொப்பமிட்ட சான்றிதழ்கள் கொண்ட சோதனை சூழல்களில் மட்டுமே இதை அணைத்து விடவும் &mdash; உற்பத்தியில் ஒருபோதும் வேண்டாம்.',
        'saved_success' => 'சேமிக்கப்பட்டது.',
        'error_saving' => 'சேமிக்க முடியவில்லை - மீண்டும் முயலவும்.',
        'no_more_fields' => 'ஒவ்வொரு புலமும் ஏற்கனவே லேபிளில் உள்ளது',
        'intune_sync_hostnames_label' => 'Intune-இல் சாதனம் மறுபெயரிடப்படும்போது சொத்துகளையும் மறுபெயரிடு',
        'intune_sync_hostnames_hint' => 'Intune-இல் மறுபெயரிடப்பட்ட அல்லது மறுஒதுக்கப்பட்ட சாதனம் அதன் சொத்துடனான இணைப்பைத் தக்கவைக்கும்; இது இயக்கத்தில் இருந்தால், அடுத்த ஒத்திசைவில் சொத்து புதிய பெயரைப் பெறும், மாற்றம் அதன் வரலாற்றில் பதிவாகும். மேம்படுத்திய பிறகு இது அணைந்திருக்கும், எனவே நீங்கள் தேர்வுசெய்யும் வரை எதுவும் மறுபெயரிடப்படாது.',
        'intune_assign_primary_user_label' => 'சொத்துகளை Intune இல் உள்ள முதன்மைப் பயனருக்கு ஒதுக்கு',
        'intune_schedule_hint' => 'பின்னணி வேலை திட்டமிடுபவர் இயங்கும்போது, இரண்டு ஒத்திசைவுகளும் தாமாகவே இயங்கும் - சாதனங்கள் ஒவ்வொரு 6 மணி நேரத்துக்கும், மென்பொருள் நாளுக்கு ஒருமுறை, பின்னணி வேலைகளில் அட்டவணை மாற்றப்படாவிட்டால். ஒத்திசை மற்றும் மென்பொருளை ஒத்திசை அவற்றை இப்போதே இயக்கும்; அந்த அழுத்தங்கள் கீழே கணக்கிடப்படுவதில்லை, அது பின்னணி வேலைகளின் இயக்கங்களைக் காட்டுகிறது.',
        'intune_schedule_link' => 'பின்னணி வேலைகள்',
        'intune_job_last' => '{job}: பின்னணி வேலைகளிலிருந்து கடைசியாக இயங்கியது {when} - {outcome}.',
        'intune_job_never' => '{job}: பின்னணி வேலைகளிலிருந்து இன்னும் இயங்கவில்லை.',
        'intune_types_label' => 'ஒவ்வொரு வகை சாதனத்துக்கும் சொத்து வகை',
        'intune_types_hint' => 'ஒவ்வொரு சாதனமும் என்ன என்பதை Intune சொல்கிறது. வகை இல்லாத சொத்துக்கு, அதன் சாதன வகைக்கு இங்கே தேர்ந்தெடுக்கப்பட்ட வகை கிடைக்கும்; ஒருவர் தேர்ந்தெடுத்த வகை ஒருபோதும் மாற்றப்படாது. Intune க்குத் தெரியாதபோது, iOS, iPadOS மற்றும் Android சாதனங்களுக்கு மற்ற மொபைல் சாதனம் வகை கிடைக்கும்; கணினிக்கு வகை எதுவும் அமைக்கப்படாது. உருவாக்கு என்பது, வகை இல்லை என்று இன்னும் அமைக்கப்பட்டுள்ள ஒவ்வொரு வகைக்கும் அதன் பெயர் குறிக்கும் வகையை, அல்லது அதன் பெயரிடப்பட்ட புதிய வகையை வழங்கி, பொருத்தத்தைச் சேமிக்கும்.',
        'intune_type_none' => 'வகை இல்லை',
        'intune_type_suggested' => 'பரிந்துரை: {name}',
        'intune_type_use' => 'பயன்படுத்து',
        'intune_types_suggested' => 'பொருந்தும் பெயருள்ள வகை அதன் சாதன வகைக்கு அருகில் பரிந்துரைக்கப்படும் - அதைத் தேர்ந்தெடுக்க பயன்படுத்து அழுத்தி, பின்னர் சேமி.',
        'intune_types_create' => 'உருவாக்கு',
        'intune_types_create_title' => 'விடுபட்ட வகைகளை உருவாக்கு',
        'intune_types_create_confirm' => 'வகை இல்லை என்று இன்னும் அமைக்கப்பட்டுள்ள ஒவ்வொரு சாதன வகைக்கும் அது அறியப்படும் சொத்து வகை கிடைக்கும், அது இல்லையென்றால் அதன் பெயரிடப்பட்ட புதிய ஒன்று. பின்னர் பொருத்தம் சேமிக்கப்படும்.',
        'intune_types_created' => 'உருவாக்கப்பட்டு பொருத்தப்பட்டது: {names}.',
        'intune_types_mapped' => 'ஏற்கனவே இருந்த வகைகளுடன் பொருத்தப்பட்டது.',
        'intune_types_none_missing' => 'ஒவ்வொரு சாதன வகைக்கும் ஏற்கனவே ஒரு வகை உள்ளது.',
        'intune_types_failed' => 'வகைகளை உருவாக்க முடியவில்லை.',
        'intune_new_type_laptop' => 'லேப்டாப்',
        'intune_new_type_desktop' => 'டெஸ்க்டாப்',
        'intune_new_type_server' => 'சேவையகம்',
        'intune_new_type_phone' => 'தொலைபேசி',
        'intune_new_type_tablet' => 'டேப்லெட்',
        'intune_new_type_other_mobile' => 'மொபைல் சாதனம்',
        'intune_kind_laptop' => 'லேப்டாப்',
        'intune_kind_desktop' => 'டெஸ்க்டாப் அல்லது பணிநிலையம்',
        'intune_kind_server' => 'சேவையகம்',
        'intune_kind_phone' => 'தொலைபேசி',
        'intune_kind_tablet' => 'டேப்லெட்',
        'intune_kind_other_mobile' => 'மற்ற மொபைல் சாதனம்',
        'intune_follow_primary_user_label' => 'முதன்மைப் பயனர் மாற்றங்களைப் பின்தொடர்',
        'intune_follow_primary_user_hint' => 'Intune இல் சாதனத்தின் முதன்மைப் பயனர் மாறும்போது, அதன் சொத்து புதிய நபருக்கு மாறும் - எந்த ஒப்படைப்பையும் போலவே பொறுப்புப் பதிவில் பதிவாகும். Intune தானே ஒருவருக்கு வழங்கிய சொத்துக்கு மட்டுமே: இங்கே தேர்ந்தெடுத்த வைத்திருப்பவர் ஒருபோதும் மாற்றப்பட மாட்டார். மேலே உள்ள அமைப்பு தேவை. நீங்கள் தேர்ந்தெடுக்கும் வரை அணைந்திருக்கும்.',
        'intune_assign_primary_user_hint' => 'யாரும் வைத்திருக்காத சொத்து, Intune இல் உள்ள அதன் சாதனத்தின் முதன்மைப் பயனருக்கு வழங்கப்படும், Entra object id மூலம் பொருத்தப்படும் - இதற்கு Microsoft Entra ID இலிருந்து இறக்குமதி செய்த நபர்கள் தேவை (கணினி → அங்கீகாரம்). ஏற்கனவே வைத்திருப்பவர் உள்ள சொத்து ஒருபோதும் மாற்றப்படாது, எதுவும் ஒதுக்கீடு நீக்கப்படாது. நீங்கள் தேர்ந்தெடுக்கும் வரை அணைந்திருக்கும்.',
        'intune_assign_primary_user_when' => 'இது ஒவ்வொரு Intune ஒத்திசைவுக்குப் பின்னும் ஒவ்வொரு Entra இறக்குமதிக்குப் பின்னும் இயங்கும், எனவே இரண்டில் எது முதலில் இயங்கினாலும் பரவாயில்லை.',
        'tab_asset_tags' => 'சொத்து குறிச்சொற்கள்',
        'asset_tags_heading' => 'தானியங்கி சொத்து குறிச்சொற்கள்',
        'asset_tags_intro' => 'ஒவ்வொரு புதிய சொத்துக்கும் வரிசையில் அடுத்த குறிச்சொல்லை வழங்கவும் - கையால் சேர்த்தாலும், இன்வென்டரி ஏஜென்ட் அல்லது Intune சேர்த்தாலும். கையால் தட்டச்சு செய்த குறிச்சொல் எப்போதும் வைத்திருக்கப்படும், இதை இயக்கும் வரை எதுவும் மாறாது.',
        'asset_tags_enable_label' => 'புதிய சொத்துகளுக்குத் தானாகக் குறிச்சொல் வழங்கு',
        'asset_tags_enable_hint' => 'குறிச்சொல் தட்டச்சு செய்யப்படாதபோது மட்டும். ஏற்கனவே உள்ள சொத்துகள் தங்கள் குறிச்சொற்களைத் தக்கவைக்கும்.',
        'asset_tags_format_label' => 'வடிவம்',
        'asset_tags_format_hint' => 'எண் வர வேண்டிய இடத்தில் {#####} வைக்கவும் - குறைந்தபட்சம் எத்தனை இலக்கங்கள் வேண்டுமோ அத்தனை #. {YYYY}, {YY}, {MM}, {DD} மற்றும் {COMPANY} (நிறுவனத்தின் டிக்கெட் குறியீடு) ஆகியவற்றையும் பயன்படுத்தலாம். டிக்கெட் எண்ணிடலில் உள்ள அதே டோக்கன்கள்.',
        'asset_tags_next_label' => 'அடுத்த எண்',
        'asset_tags_next_hint' => 'அடுத்த குறிச்சொல் கொண்டிருக்கும் எண். இதை முன்னோக்கி மட்டுமே நகர்த்த முடியும்: ஏற்கனவே வழங்கப்பட்ட எண் மீண்டும் வழங்கப்படாது.',
        'asset_tags_scope_label' => 'எண்ணிடல்',
        'asset_tags_scope_per_company' => 'ஒவ்வொரு நிறுவனத்துக்கும் தனித்தனியாக',
        'asset_tags_scope_global' => 'எல்லா நிறுவனங்களுக்கும் சேர்த்து ஒரே முறை',
        'asset_tags_scope_hint' => 'ஒவ்வொரு நிறுவனத்துக்கும் பொருந்தும். குறிச்சொற்கள் ஒரு நிறுவனத்துக்குள் மட்டும் தனித்துவமாக இருந்தால் போதும், எனவே தனித்தனியாக எண்ணுவதே வழக்கம்.',
        'asset_tags_preview_label' => 'அடுத்த குறிச்சொற்கள்',
        'asset_tags_saved' => 'சொத்து குறிச்சொல் அமைப்புகள் சேமிக்கப்பட்டன.',
        'tab_asset_labels' => 'சொத்து லேபிள்கள் & QR',
        'asset_labels_heading' => 'பௌதீக சொத்து லேபிள்கள் & QR தனிப்பயனாக்கம்',
        'asset_labels_intro' => 'பௌதீக லேபிள் பிராண்டிங், அமைப்பு மண்டலங்கள் மற்றும் உட்பொதிக்கப்பட்ட QR லோகோக்களை உள்ளமைக்கவும். சொத்துப் பதிவேட்டிலிருந்து அச்சிடப்படும் அல்லது அச்சகத்துக்கு ஏற்றுமதி செய்யப்படும் லேபிள்கள் இந்த அமைப்புகளைப் பயன்படுத்தும்.',
        'asset_label_title_label' => 'தலைப்பு / நிறுவன உரை (விருப்பத்தேர்வு)',
        'asset_label_title_hint' => 'ஒவ்வொரு லேபிளின் மேலேயும் அச்சிடப்படும் உரை (எ.கா. IT-யின் சொத்து, நிறுவனத்தின் பெயர்). தலைப்பு வேண்டாம் என்றால் வெறுமையாக விடவும்.',
        'asset_label_title_ph' => 'எ.கா. IT துறையின் சொத்து',
        'asset_label_fields_label' => 'அச்சிடப்படும் லேபிள் புலங்கள்',
        'asset_label_fields_hint' => 'பௌதீக சொத்து லேபிள்களில் அச்சிடப்படும் புலங்களைத் தேர்ந்தெடுத்து வரிசையாக அமைக்கவும். சொத்து குறிச்சொல் கட்டாயம்.',
        'asset_label_show_labels_label' => 'அச்சிடப்படும் குறிச்சொல்லில் புலப் பெயர்களைச் சேர்',
        'asset_label_show_labels_hint' => 'இயக்கப்பட்டால், மதிப்புகளுக்கு முன் புலப் பெயர்களை அச்சிடும் (எ.கா. "Hostname: LON-01"). அணைக்கப்பட்டால், இடத்தை அதிகம் சேமிக்க மதிப்புகளை மட்டும் அச்சிடும்.',
        'asset_label_add_field' => 'புலத்தைச் சேர்',
        'asset_label_mandatory' => 'கட்டாயம்',
        'asset_label_density_warn' => 'தேர்ந்தெடுத்த புலங்கள் சிறிய லேபிள் தாள்களில் நெருக்கமான இடைவெளியை ஏற்படுத்தலாம். படிக்க எளிதாக உரை தானாகவே சிறிதாகி, நீள்வட்டக் குறியுடன் துண்டிக்கப்படும்.',
        'asset_label_subtitle_label' => 'இரண்டாம் நிலைப் புலம்',
        'asset_label_subtitle_hint' => 'முதன்மையான சொத்து குறிச்சொல்லின் கீழே அச்சிடப்படும் புலம்',
        'asset_label_subtitle_hostname' => 'ஹோஸ்ட்பெயர்',
        'asset_label_subtitle_serial' => 'வரிசை எண் / சர்வீஸ் டேக்',
        'asset_label_subtitle_model' => 'உற்பத்தியாளர் & மாடல்',
        'asset_label_subtitle_none' => 'எதுவுமில்லை (குறிச்சொல் மட்டும்)',
        'asset_label_footer_label' => 'அடிக்குறிப்பு / ஆதரவு உரை (விருப்பத்தேர்வு)',
        'asset_label_footer_hint' => 'ஒவ்வொரு லேபிளின் அடியிலும் அச்சிடப்படும் சிறிய ஆதரவு அறிவிப்பு அல்லது தொடர்புத் தகவல்',
