        'asset_label_logo_restrictions_hint' => 'லோகோ வடிவம்: PNG அல்லது JPG மட்டும், அதிகபட்சம் 2 MB. சதுர, தடித்த அல்லது அதிக மாறுபாடுள்ள லோகோக்கள் சிறப்பாக வேலை செய்யும். நம்பகமான ஸ்கேனிங்கை உறுதிசெய்ய, Error Correction Level H (30% மிகைமை) உடன் QR குறியீட்டின் மையத்தில் 22% ஆக அளவிடப்படுகிறது.',
