        'protect_check' => 'ஒரு கருவி அறிக்கையிடும் சொத்தின் பெயர், உற்பத்தியாளர் அல்லது மாடலை யாராவது திருத்தினால், அது மேலெழுதப்படாமல் பாதுகாக்கவும்',
        'protect_hint' => 'இல்லையெனில் ஏஜென்ட் அல்லது Intune அடுத்த அறிக்கையில் தனது சொந்த மதிப்பை மீண்டும் வைக்கும். எந்த மதிப்பையும் அதன் அருகிலுள்ள பூட்டு மூலம் கைமுறையாகவும் பாதுகாக்கலாம் அல்லது விடுவிக்கலாம்.',
        'stale_days_label' => 'Inventory இத்தனை நாட்களுக்குப் பிறகு காலாவதி எனக் கருதப்படும் (நாட்கள்)',
        'stale_days_hint' => 'இதைவிடப் பழைய inventory பட்டியல் சொத்தில் அம்பர் நிறத்தில் காட்டப்படும் - அதன் பட்டியலுக்கு மேலும் Inventory மூலங்கள் பலகத்திலும். உங்கள் மூலங்கள் எவ்வளவு அடிக்கடி அறிக்கையிடுகின்றன என்பதற்கு ஏற்ப அமைக்கவும்: தினமும் இயங்கும் ஏஜென்டுக்கு 7 நாட்கள் பொருந்தும்.',
        'reconciliation_heading' => 'சொத்துக் கண்டறிதலும் இணக்கப்படுத்தலும்',
        'reconciliation_intro' => 'தானியங்கி வன்பொருள் கண்டறிதல் மூலங்கள் அனைத்திலும் (PowerShell இன்வென்டரி ஏஜென்ட், Intune மற்றும் எதிர்காலக் கண்டறிதல் இணைப்பிகள்) அடையாள இணக்கப்படுத்தல் விதிகளையும் புறக்கணிக்கப்பட்ட வரிசை எண்களையும் உள்ளமைக்கவும்.',
        'batch_size_label' => 'மென்பொருள் ஒத்திசைவு தொகுதி அளவு',
        'batch_size_hint' => 'ஒரே மென்பொருள்-ஒத்திசைவு வேலையில் சேர்க்கப்படும் சாதனங்களின் எண்ணிக்கை (1–500). சிறிய தொகுதிகள் விரைவாக முடியும் ஆனால் முழு எஸ்டேட்டையும் உள்ளடக்க அதிக கிளிக்குகள் தேவை.',
        'intune_company_label' => 'நிறுவனம் / டெனன்ட் வரம்பு',
