        'default_company' => 'இயல்புநிலை நிறுவனம்',
        'ignored_serials_label' => 'புறக்கணிக்கப்பட்ட வரிசை எண்கள் / சர்வீஸ் டேக்குகள்',
        'ignored_serials_hint' => 'சொத்து இணக்கப்படுத்தலின் போது புறக்கணிக்கப்பட வேண்டிய வரிசை எண்/சர்வீஸ் டேக் மதிப்புகளை உள்ளிடவும். ஒரு சாதனத்தை ஏற்கனவே உள்ள சொத்துடன் பொருத்த இந்த மதிப்புகள் பயன்படுத்தப்படாது. பொருத்துதல் பெரிய/சிறிய எழுத்து வேறுபாடு பார்ப்பதில்லை.',
