        'localhost_warn_body' => 'தொலைபேசியைப் பொறுத்தவரை <code>localhost</code> என்றால் தொலைபேசியே. இந்த நிறுவலை அணுகும் முகவரியை (<strong>டிக்கெட்டுகள் → அமைப்புகள் → செய்தியிடல் → Public base URL</strong>) அமைத்து மீண்டும் அச்சிடுங்கள் — குறியீடுகள் மாறாது, அவற்றின் உள்ளே உள்ள முகவரி மட்டுமே மாறும்.',
