        'intro' => 'லேபிள் எப்படித் தெரிகிறது, எதில் அச்சாகிறது. லேபிளை அச்சிடு இயல்புநிலை வடிவமைப்பைப் பயன்படுத்தும்; அச்சிடும்போது வேறொன்றைத் தேர்ந்தெடுக்கலாம். லேபிள்கள் அதன் சரியான அளவில் PDF ஆக அச்சாகின்றன - உங்கள் லேபிள் பிரிண்டரின் சொந்த டிரைவர் மூலம் "Actual size" இல் அச்சிடவும்.',
