        'custom_size' => 'அகலம் x உயரம்',
        'offset' => 'பிரிண்டர் ஆஃப்செட் (வலது, கீழ்)',
        'offset_hint' => 'தாளில் லேபிள்கள் சற்று நேர்கோட்டில் இல்லாமல் அச்சானால், 10 மிமீ வரை நகர்த்தவும். முதலில் சாதாரண தாளில் அச்சிட்டு, அதை லேபிள் தாளுடன் பிடித்துப் பாருங்கள்.',
        'font' => 'எழுத்துரு',
        'mono' => 'கருப்பு-மட்டும் பிரிண்டர்',
        'mono_hint' => 'அனைத்து உரையையும் கோடுகளையும் முழுக் கருப்பிலும், லோகோவை தூய கருப்பு வெள்ளையிலும் அச்சிடும். டேப் மற்றும் ரோல் பிரிண்டர்களால் சாம்பல் நிறத்தை அச்சிட முடியாது, அவை படிக்க கடினமான புள்ளிகளாக அச்சிடுகின்றன. வண்ண லேபிள்களுக்கு இதை அணைத்து வைக்கவும்.',
        'make_default' => 'லேபிளை அச்சிடுவதற்கு இந்த வடிவமைப்பைப் பயன்படுத்து',
        'default' => 'இயல்புநிலை',
        'set_default' => 'இயல்புநிலையாக்கு',
