        'delete_body' => '"{name}" வடிவமைப்பை நீக்கவா?',
        'standard_name' => 'நிலையான',
        'tpl_standard' => 'நிலையான - குறிச்சொல் மற்றும் புலங்களுக்கு அருகில் QR',
        'tpl_tape_logo_left' => 'இடதில் லோகோ, நடுவில் விவரங்கள், வலதில் QR',
        'tpl_tape_small' => 'சிறியது - QR மற்றும் குறிச்சொல் மட்டும்',
