        'tpl_hint_standard' => 'FreeITSM எப்போதும் அச்சிட்ட லேபிள்: தலைப்பு, QR, குறிச்சொல் மற்றும் கீழே நீங்கள் தேர்ந்தெடுக்கும் புலங்கள், அடிக்குறிப்பு.',
        'tpl_hint_tape_logo_left' => 'Brother 24 மிமீ போன்ற டேப் லேபிள்களுக்கு: இடதில் பெரிய லோகோ, நடுவில் தலைப்பும் புலங்களும், வலதில் QR குறியீடு.',
        'tpl_hint_tape_small' => 'சிறிய லேபிள்கள் மற்றும் குறுகிய டேப்புக்கு: QR குறியீடு மற்றும் சொத்து குறிச்சொல்.',
        'tpl_hint_sheet_large' => 'பெரிய லேபிள்களுக்கு: மேலே முழுவதும் உங்கள் லோகோ, QR குறியீடு, அதன் கீழே புலங்கள்.',
        'tpl_custom' => 'உங்கள் சொந்த வடிவமைப்பு',
        'open_designer' => 'வடிவமை',
        'size_fixed' => 'இந்த வடிவமைப்பு இந்த அளவுக்காக அமைக்கப்பட்டது. வடிவமைப்பாளரில் அளவை மாற்றவும்.',
        'fonts_title' => 'லேபிள் எழுத்துருக்கள்',
        'fonts_intro' => 'லேபிள்கள் Noto Sans ஐப் பயன்படுத்துகின்றன, இது மேற்கு மற்றும் கிழக்கு ஐரோப்பிய மொழிகள், கிரேக்கம், சிரிலிக் மற்றும் வியட்நாமியத்தை உள்ளடக்கியது. உங்கள் சொத்துப் பெயர்கள் உள்ள வேறு எந்த மொழிக்கும், அல்லது உங்கள் சொந்த பிராண்ட் எழுத்துருவுக்கு, ஒரு எழுத்துருவைப் பதிவேற்றவும். ஒரு எழுத்துருவில் இல்லாத எழுத்து அடுத்ததிலிருந்து வரையப்படும்.',
        'fonts_none' => 'எழுத்துருக்கள் எதுவும் பதிவேற்றப்படவில்லை - லேபிள்கள் Noto Sans ஐப் பயன்படுத்தும்.',
        'font_upload' => 'பதிவேற்று',
        'font_upload_title' => 'எழுத்துருவைப் பதிவேற்று',
        'font_file' => 'எழுத்துருக் கோப்பு',
        'font_file_hint' => 'TTF, OTF, WOFF அல்லது WOFF2, 20 MB வரை.',
        'font_licence' => 'நான் அச்சிடும் ஆவணங்களில் இந்த எழுத்துருவைப் பயன்படுத்தலாம். சில வணிக எழுத்துருக்கள் இதை அனுமதிப்பதில்லை.',
