        'font_in_use' => 'இந்த எழுத்துரு இவற்றால் பயன்படுத்தப்படுகிறது: {designs}. முதலில் அவற்றுக்கு வேறு எழுத்துருவைத் தேர்ந்தெடுக்கவும்.',
