        'changed_meanwhile' => 'நீங்கள் திறந்ததிலிருந்து வேறொருவர் இந்த வடிவமைப்பை மாற்றிவிட்டார். பக்கத்தை மீண்டும் ஏற்றி முயற்சிக்கவும்.',
