        'not_ready' => 'லேபிள் வடிவமைப்புகளுக்கு முதலில் தரவுத்தளப் புதுப்பிப்பு தேவை - நிர்வாகி கணினி -> தரவுத்தள சரிபார்ப்பை இயக்கலாம்.',
