        'hint_sheet' => 'PDF ஐ "Actual size" இல் அச்சிடவும் - ஒருபோதும் "Fit to page" அல்ல - லேபிள் தாளைப் பயன்படுத்தும் முன் சாதாரண தாளில் சீரமைப்பைச் சரிபார்க்கவும்.',
        'hint_tape' => 'ஒரு பக்கத்துக்கு ஒரு லேபிள், பக்கம் லேபிளின் சரியான அளவில். PDF ஐ உங்கள் லேபிள் பிரிண்டரின் சொந்த டிரைவர் மூலம், அதில் பொருந்தும் டேப் அல்லது லேபிள் அளவைத் தேர்ந்தெடுத்து, "Actual size" இல் அச்சிடவும்.',
