    'help' => [
        'missing' => [
            'nav' => 'விடுபட்ட தகவல்',
            'heading' => 'விடுபட்ட தகவல்',
            'intro' => 'ஒரு சொத்தை முதல் நாளில் உங்களுக்குத் தெரிந்தவற்றுடன் - அதன் பெயர், வகை மற்றும் வரிசை எண் - பதிவு செய்து, மீதியைப் பின்னர் நிரப்பலாம். <strong>எதிர்பார்க்கப்படும் தகவல்</strong> ஒவ்வொரு சொத்து வகைக்கும் இறுதியில் எந்தப் புலங்கள் இருக்க வேண்டும் என்று சொல்கிறது, <strong>விடுபட்ட தகவல்</strong> ஒன்று இல்லாத ஒவ்வொரு சொத்தையும் புலத்தின் பெயருடன் பட்டியலிடுகிறது. எதுவும் மறுக்கப்படுவதில்லை: பக்கம், இறக்குமதிகள், REST API மற்றும் inventory agent முன்பு போலவே சேமிக்கின்றன.',
            'p1' => '<strong>புலங்களைத் தேர்ந்தெடுங்கள்:</strong> அமைப்புகள் -> சொத்து வகைகள் -> ஒரு வகை -> <strong>எதிர்பார்க்கப்படும் தகவல்</strong>. உள்ளமைந்த புலங்களை (அடையாளம், தயாரிப்பு மற்றும் மாடல், நிதி) மற்றும் அந்த வகையுடன் இணைக்கப்பட்ட புலத் தொகுப்புகளில் உள்ள எந்தத் தனிப்பயன் புலத்தையும் குறிக்கவும். வகையின் அமைப்பில் ஒரு பிரிவை மறைப்பதால் அதன் புலங்கள் பொருந்தாதவை ஆகாது.',
            'p2' => '<strong>பட்டியலை முடியுங்கள்:</strong> ஒரு வகை ஏதாவது எதிர்பார்க்கும்போது தலைப்பில் <strong>விடுபட்ட தகவல்</strong> பொத்தான் தோன்றும். வகை, பிரிவு (எடுத்துக்காட்டாக நிதி) அல்லது புலத்தின்படி வடிகட்டவும்; ஒரு சொத்தைத் திறக்க கிளிக் செய்யவும். புலத்தை - எங்கு வேண்டுமானாலும் - நிரப்பினால் அது உடனே பட்டியலிலிருந்து நீங்கும்; அழித்தால் திரும்ப வரும்.',
            'p3' => '<strong>விடுபட்டது</strong> என்றால் காலியானது: மதிப்பு இல்லை, வெற்று உரை அல்லது தேர்வு இல்லை. 0 செலவு அல்லது "இல்லை" என்பது நிரப்பப்பட்டதாகக் கணக்கிடப்படும் - மதிப்பு இருக்கிறதா என்பதே சோதனை, அது சரியானதா என்பதல்ல. ஓய்வுபெற்ற சொத்துகள் பட்டியலிடப்படாது.',
            'p4' => '<strong>பொருந்தாது</strong> ஒரு சொத்துக்கு ஒரு புலத்தை ஒதுக்கி வைக்கிறது - வாங்கிய செலவு இல்லாத நன்கொடை லேப்டாப், எடுத்துக்காட்டாக. இது புலத்தில் எதையும் எழுதாது, சொத்தின் வரலாற்றில் பதிவாகும், மேலும் சொத்தில் <strong>செயல்தவிர்</strong> உடன் காட்டப்படும். இதற்கு Assets-க்கான எழுது அணுகல் தேவை.',
        ],
        'retired' => [
            'nav' => 'ஓய்வுபெற்ற சொத்துகள்',
            'heading' => 'ஓய்வுபெற்ற சொத்துகள்',
            'intro' => 'அகற்றப்பட்ட, செயலிழக்கப்பட்ட அல்லது வேறொரு நிறுவனத்துக்கு மாற்றப்பட்ட உபகரணங்கள் - பதிவாக வைக்கப்படும், ஆனால் இனி செயலில் உள்ள சொத்தாகக் கணக்கிடப்படாது.',
            'p1' => '<strong>"ஓய்வுபெற்றது" என்பதற்கு என்ன பெயர் என்று தேர்ந்தெடுங்கள்.</strong> <strong>அமைப்புகள் &rarr; சொத்து நிலைகள்</strong> என்பதில் ஒரு நிலையைத் ("ஓய்வுபெற்றது", "அகற்றப்பட்டது", "மாற்றப்பட்டது") திருத்தி <strong>ஓய்வுபெற்றது</strong> என்பதைக் குறிக்கவும். நீங்கள் செய்யும் வரை எதுவும் ஓய்வுபெறாது.',
            'p2' => '<strong>ஒரு சொத்தை ஓய்வு பெறச் செய்ய</strong> அந்த நிலையைக் கொடுங்கள். அதில் தேதி முத்திரையிடப்படும், ஒரு காரணத்தையும் ("கல்வி அமைச்சகத்துக்கு மாற்றப்பட்டது") சேர்க்கலாம், மேலும் அது சொத்துப் பட்டியல், Table, dashboard, Watchtower, உத்தரவாதம் மற்றும் குத்தகை எச்சரிக்கைகள் மற்றும் நாட்காட்டியிலிருந்து நீங்கும். மீண்டும் சாதாரண நிலையைக் கொடுத்தால் திரும்ப வரும்.',
            'p3' => 'பட்டியலுக்கு மேலே (மற்றும் Table-இல்) உள்ள <strong>ஓய்வுபெற்றவற்றைக் காட்டு</strong> ஓய்வுபெற்ற சொத்துகளை மீண்டும் காட்சிக்குக் கொண்டு வரும். Table <strong>ஓய்வுபெற்ற தேதி</strong> மற்றும் <strong>காரணம்</strong> நெடுவரிசைகளைக் காட்டி அவற்றை CSV அல்லது PDF ஆக ஏற்றுமதி செய்யலாம் - மாற்றத்துடன் அனுப்பும் பட்டியல். Report Packs-இல் உள்ள <strong>ஓய்வுபெற்ற சொத்துகள்</strong> தொகுதி ஒரு காலகட்டத்தில் ஓய்வுபெற்றவற்றைப் பட்டியலிடும்.',
            'p4' => 'இன்னும் அறிக்கை அனுப்பும் ஓய்வுபெற்ற இயந்திரம் (inventory agent, Intune) அடையாளம் காணப்படும் - நகல் உருவாக்கப்படாது - ஆனால் அதன் பதிவு மாற்றப்படாது: அதன் <em>கடைசியாகக் காணப்பட்டது</em> மட்டுமே நகரும், எனவே இன்னும் நெட்வொர்க்கில் உள்ள ஓய்வுபெற்ற இயந்திரம் தெரியவரும்.',
        ],
        'review_heading' => 'இரண்டு பதிவுகள் ஒன்றாக இருக்கக்கூடும்போது',
        'review_body' => 'FreeITSM ஒருபோதும் ஊகிப்பதில்லை. இரண்டு சொத்துகள் ஒரே வரிசை எண்ணைப் பகிரும்போது, agent ஒரு பழைய இயந்திரத்தின் பெயரைக் கொண்ட புதிய இயந்திரத்தைக் கண்டறியும்போது, அல்லது ஒரு கருவி எந்தச் சொத்துடனும் (அல்லது பலவற்றுடன்) பொருந்தாத வரிசை எண் கொண்ட சாதனத்தைப் புகாரளிக்கும்போது, அந்த கேஸ் ஒரு நபர் முடிவு செய்ய <strong>அமைப்புகள் &rarr; மதிப்பாய்வு</strong> என்பதில் காத்திருக்கும். பட்டியலில் உள்ள சொத்து அதன் முக்கியத் தகவலில் இதைச் சொல்லும். இரண்டு சொத்துகளுக்கு: அவற்றை <strong>ஒன்றிணை</strong>, <strong>வேறுபட்டவை</strong> எனக் குறி (உண்மையிலேயே இரண்டு), அல்லது <strong>புறக்கணி</strong>. தெரியாத சாதனத்துக்கு: அதைச் சொத்தாக <strong>உருவாக்கு</strong> (கருவி அதைக் கண்ட இடத்துடன் இணை), அல்லது புறக்கணி. முடிவுகளை <em>முடிவு செய்யப்பட்டவை</em> என்பதன் கீழ் மீண்டும் திறக்கலாம், தானாகத் தீர்ந்துவிடும் கேஸ் தானாகவே மூடப்படும்.',
        'merge_body' => '<strong>ஒன்றிணைத்தல் எல்லாவற்றையும் வைத்திருக்கும்.</strong> வைத்திருக்க வேண்டிய பதிவை நீங்கள் தேர்ந்தெடுக்கிறீர்கள்; மற்றதில் உள்ள அனைத்தும் அதற்கு நகரும் - வரலாறு, டிக்கெட்டுகள், ஒப்பந்தங்கள், ஆவணங்கள், திட்டங்கள், குத்தகைகள், பொறுப்பு, இணைப்புகள், தனிப்பயன் புல மதிப்புகள் மற்றும் inventory. இரண்டிலும் ஒரே விஷயம் இருந்தால், நீங்கள் வைத்திருப்பது வெல்லும், காலியான புலம் மற்றதிலிருந்து நிரப்பப்படும். பிறகு மற்ற பதிவு அகற்றப்படும், ஆனால் அதன் அச்சிடப்பட்ட QR லேபிள், அதற்கான இணைப்புகள் மற்றும் REST API மூலம் அதற்கு அறிக்கை அனுப்பும் கருவிகள் அனைத்தும் நீங்கள் வைத்திருந்ததைக் கண்டுபிடிக்கும். ஒன்றிணைப்பைச் செயல்தவிர்க்க முடியாது, மேலும் Discovery &amp; reconciliation அனுமதி உள்ளவர் மட்டுமே செய்ய முடியும்.',
        'protect_heading' => 'நிலைக்கும் திருத்தங்கள்',
        'protect_body' => 'agent மற்றும் Intune ஒவ்வொரு அறிக்கையிலும் <strong>பெயர்</strong>, <strong>உற்பத்தியாளர்</strong> மற்றும் <strong>மாடல்</strong> ஆகியவற்றை எழுதுகின்றன, இது "Hewlett-Packard" போன்ற திருத்தத்தை அடுத்த ஒத்திசைவில் செயல்தவிர்த்துவிடும். அந்தப் புலங்களில் ஒன்றின் அருகிலுள்ள <strong>பூட்டை</strong> கிளிக் செய்து பாதுகாக்கவும்: எந்த அறிக்கைக் கருவியும் அதை மேலெழுதாது, கருவி வேறு ஏதாவது புகாரளித்தால் அது புலத்தின் கீழே (<em>agent "HP" எனப் புகாரளிக்கிறது</em>) காட்டப்படும், கருவி மீண்டும் வெல்ல <strong>விடு</strong> என்பதைப் பயன்படுத்தலாம். ஒரு கருவி புகாரளிக்கும் சொத்தில் இந்தப் புலங்களில் ஒன்றைத் திருத்தினால் அது தானாகப் பாதுகாக்கப்படும் - அதை <strong>அமைப்புகள் &rarr; Discovery &amp; reconciliation</strong> என்பதில் அணைக்கலாம். வரிசை எண்ணைப் பாதுகாக்க முடியாது, ஏனெனில் பொருத்தம் அதைச் சார்ந்துள்ளது. நபர்கள் - இந்தப் பக்கத்தில், REST API மூலம் அல்லது இறக்குமதி மூலம் - பாதுகாக்கப்பட்ட மதிப்பை இன்னும் மாற்றலாம்.',
        'names_heading' => 'ஒரு தயாரிப்பாளருக்கு ஒரு பெயர்',
        'names_body' => 'HP, HP Inc. மற்றும் Hewlett-Packard ஒரே தயாரிப்பாளர், ஆனால் உற்பத்தியாளர் வாரியான வரைபடம் மூன்று துண்டுகளைக் காட்டுகிறது. <strong>அமைப்புகள் &rarr; Discovery &amp; reconciliation &rarr; உற்பத்தியாளர் மற்றும் மாடல் பெயர்கள்</strong> என்பதில் ஒவ்வொரு எழுத்துப்பிழைக்கும் காட்ட வேண்டிய பெயரைத் தேர்ந்தெடுங்கள். அட்டவணைக் காட்சி, அதன் வடிகட்டிகள், சொத்துப் பட்டியலின் தேடல் மற்றும் dashboard வரைபடங்கள் நீங்கள் தேர்ந்த பெயரைப் பயன்படுத்தும்; ஒவ்வொரு சொத்தும் புகாரளிக்கப்பட்டதை வைத்திருக்கும் (முக்கியத் தகவல் அதன் கீழ் <em>HP எனக் காட்டப்படுகிறது</em> என்று சொல்லும்), எனவே ஒரு வரியை நீக்கினால் அது செயல்தவிர்க்கப்படும். லேபிள்கள், ஒப்படைப்பு ஆவணங்கள் மற்றும் பிற அச்சுகள் சேமிக்கப்பட்ட மதிப்பைக் காட்டும்.',
        'connected_heading' => 'எது எதனுடன் இணைக்கப்பட்டுள்ளது',
        'connected_body' => '<strong>இணைக்கப்பட்டவை</strong> தாவல் ஒரு சொத்துடன் நேரடியாக இணைக்கப்பட்டவற்றைக் காட்டுகிறது - கணினியில் ஒரு மானிட்டர், டாக்கில் ஒரு தொலைபேசி - மேலும் அது <strong>இரு முனைகளிலிருந்தும்</strong> தெரியும்: மானிட்டர் கணினியைப் பட்டியலிடும், கணினி மானிட்டரைப் பட்டியலிடும். நீங்களே ஒன்றைப் பதிவு செய்ய <strong>இணை</strong> என்பதைப் பயன்படுத்தவும்: மற்ற சொத்தைப் பெயர், வரிசை எண் அல்லது சொத்துக் குறிச்சொல் மூலம் தேடுங்கள். இரண்டும் ஒரே நிறுவனத்தில் இருக்க வேண்டும். REST API மூலம் அறிக்கை அனுப்பும் கருவியும் தான் காண்பதைப் பதிவு செய்யலாம், அதன் வரிசை <em>கடைசியாக lansweeper 3 hr முன்பு இணைக்கப்பட்டதாகக் கவனித்தது</em> என்று சொல்லும் - அது கடைசியாகக் கண்டபோது, இப்போது இணைந்திருக்கிறது என்பதல்ல. <strong>உறுதிப்படுத்து</strong> ஒரு கருவியின் உறுதிப்படுத்தலுக்கு அருகில் உங்கள் சொந்த உறுதிப்படுத்தலைச் சேர்க்கும். ஒவ்வொரு இணைப்பும் துண்டிப்பும் இரு சொத்துகளின் வரலாற்றிலும் இருக்கும், முடிந்தவை <strong>முந்தைய இணைப்புகள்</strong> என்பதன் கீழ் இருக்கும்.',
        'connected_rules' => '<strong>ஒவ்வொரு மூலமும் தன் சொந்த வரிசையை வைத்திருக்கும்.</strong> நீங்கள் உறுதிப்படுத்தியதும் ஒரு கருவி கண்டதும் அருகருகே இருக்கும், ஒன்றையொன்று மேலெழுதாது: கருவி உங்கள் இணைப்பை ஒருபோதும் முடிக்காது, <strong>துண்டி</strong> ஒரு நபர் உறுதிப்படுத்தியதை மட்டுமே முடிக்கும். ஒரு அறிக்கை குறிப்பிட மறந்ததால் எதுவும் துண்டிக்கப்படாது - அதைக் கண்ட கருவி மட்டுமே அது போய்விட்டது என்று சொல்ல முடியும். இணைப்பு என்பது பொறுப்பு (யார் வைத்திருக்கிறார்கள்) அல்ல, CMDB சார்பும் அல்ல. ஒரு மானிட்டர் ஒரு கணினியுடன் இணைக்கப்பட்டு ஒரு நபருக்கு வழங்கப்பட்டிருக்கலாம், ஒன்று மற்றொன்றை மாற்றாது. இந்தத் தாவலையும் மற்றவற்றைப் போலவே சொத்து வகைக்கு ஏற்ப மறைக்கலாம்.',
        'freshness_heading' => 'ஒவ்வொரு பட்டியலும் எவ்வளவு புதியது?',
        'freshness_body' => '<strong>சேமிப்பகம்</strong>, <strong>சாதனங்கள்</strong> மற்றும் <strong>மென்பொருள்</strong> ஆகியவற்றுக்கு மேலே, எந்தக் கருவி பட்டியலைப் புகாரளித்தது, எப்போது பார்த்தது என்று ஒரு வரி சொல்லும்: <em>agent-இடமிருந்து, 3 hr முன்பு கவனிக்கப்பட்டது.</em> அது <strong>அமைப்புகள் &rarr; Discovery &amp; reconciliation &rarr; Inventory பழையதாகக் கருதப்படும் காலம்</strong> என்பதை விடப் பழையதானதும் (மாற்றாவிட்டால் 7 நாட்கள்) <strong>அம்பர்</strong> ஆகும். கடைசி அறிக்கை விட்டுவிட்ட பட்டியல் அதைச் சொல்லும், <strong>தோல்வியடைந்த</strong> சேகரிப்பு பிழையுடன் சிவப்பில் காட்டப்படும் - முந்தைய பட்டியல் அதன் சொந்த வயதுடன் வைக்கப்படும். Key info-வின் கீழ் உள்ள <strong>Inventory மூலங்கள்</strong> பலகம் சொத்தைப் புகாரளிக்கும் ஒவ்வொரு கருவியையும் அது வைத்திருக்கும் ஒவ்வொரு பட்டியலையும் காட்டும், எந்த வகையின் அமைப்பும் அதை மறைக்காது. எந்தப் பட்டியலையும் எதுவும் புகாரளிக்காதபோது அதைச் சொல்லும், தாவல் எண்ணிக்கை கோடு காட்டும், எனவே <strong>0</strong> என்றால் ஒரு கருவி பார்த்து எதுவும் காணவில்லை என்றே பொருள்.',
        'freshness_agent' => '<strong>காலியாகப் புகாரளிக்கப்பட்டது</strong> மற்றும் <strong>தோல்வி</strong> 3.15.0 உடன் வரும் agent ஸ்கிரிப்டிலிருந்து வருகின்றன. பழைய ஸ்கிரிப்ட் "எதுவும் இல்லை" என்பதையும் "பார்க்க முடியவில்லை" என்பதையும் பிரித்தறிய முடியாது, எனவே அதன் காலிப் பட்டியல்கள் புகாரளிக்கப்படாதவையாகக் கருதப்பட்டு முந்தைய பட்டியல் முன்பு போலவே வைக்கப்படும். மேம்படுத்தலுக்கு முன் புகாரளிக்கப்பட்ட சொத்துகள் அடுத்த அறிக்கை வரை வரியைக் காட்டாது.',
        'layout_heading' => 'சொத்தின் வகைக்குப் பொருந்தும் பக்கம்',
        'layout_body' => 'ஒவ்வொரு சொத்து வகையும் அதன் சொத்துகள் எந்த உள்ளமைந்த விவரங்களையும் தாவல்களையும் காட்டும் என்று முடிவு செய்கிறது. மானிட்டருக்கு CPU, நினைவகம் அல்லது சாதனங்கள் தாவல் தேவையில்லை, எனவே அதன் வகை அவற்றை மறைக்கலாம், தாவல்களை அதற்குப் பொருந்தும் வரிசையில் வைக்கலாம். இதை <strong>அமைப்புகள் &rarr; சொத்து வகைகள்</strong> என்பதில் அமைக்கவும்: ஒரு வகையைத் திருத்தி <strong>அமைப்பு</strong> என்பதைப் பயன்படுத்தவும், அல்லது ஒரு தொடக்கப் புள்ளியைத் (Peripheral, Network equipment, Mobile device) தேர்ந்தெடுத்து குறிகளைச் சரிசெய்யவும். பெயர், சொத்துக் குறிச்சொல், வரிசை எண், வகை, நிலை, இடம் மற்றும் நிறுவனம் எப்போதும் காட்டப்படும், முக்கியத் தகவல் எப்போதும் முதலில் வரும்.',
        'layout_hidden' => '<strong>மறைத்தல் பக்கத்தைப் பற்றியது மட்டுமே.</strong> எதுவும் நீக்கப்படாது, agent மற்றும் இறக்குமதிகள் ஒவ்வொரு புலத்தையும் தொடர்ந்து பதிவு செய்யும், அட்டவணைக் காட்சியும் API-யும் இன்னும் எல்லாவற்றையும் காட்டும். ஒரு சொத்தில் அதன் வகை மறைக்கும் விவரங்கள் இருந்தால் - தவறான வகை கொடுக்கப்பட்ட கணினி என்று வைத்துக்கொள்ளுங்கள் - முக்கியத் தகவல் அதைச் சொல்லும் (<em>இந்த வகையின் அமைப்பால் மறைக்கப்பட்டது: மென்பொருள் (214)</em>) மேலும் <strong>அவற்றைக் காட்டு</strong> என்பது அந்தச் சொத்துக்கு மறைக்கப்பட்ட ஒவ்வொரு பிரிவையும் தாவலையும் கோடிட்ட வெளிக்கோட்டுடன் திரும்பக் கொண்டு வரும். <strong>அமைப்புகள் &rarr; சொத்து வகைகள் &rarr; ஒரு வகை மறைக்கும் விவரங்கள்</strong> அதை அமைதியான <em>மறைக்கப்பட்டதைக் காட்டு</em> இணைப்பாக மாற்றலாம்.',
        'proxmox' => [
            'nav' => 'Proxmox VE சேவையகங்கள்',
            'heading' => 'Proxmox VE சேவையகங்கள்',
            'intro' => 'FreeITSM ஒன்று அல்லது அதற்கு மேற்பட்ட Proxmox VE சேவையகங்களிலிருந்து மெய்நிகர் இயந்திரங்கள், LXC கண்டெய்னர்கள், நோடுகள், IP மற்றும் MAC முகவரிகளைப் படித்து, vCenter-க்கு அருகில் <strong>சேவையகங்கள்</strong> பிரிவின் கீழ் பட்டியலிடும். இது படிப்பதை மட்டுமே செய்கிறது: Proxmox-இல் எதுவும் மாற்றப்படாது. சேவையகங்களை <strong>அமைப்புகள் &rarr; Proxmox VE சேவையகங்கள்</strong> என்பதன் கீழ் சேர்க்கவும்; ஒவ்வொன்றும் தனது சொந்த அட்டவணைப்படி ஒத்திசைக்கும்.',
            'user_heading' => '1. FreeITSM-க்கான பயனர் மற்றும் படிக்க-மட்டும் பங்கு',
            'user_1' => 'Proxmox-இல், <strong>Datacenter &rarr; Permissions &rarr; Users &rarr; Add</strong>: <code>freeitsm</code> போன்ற ஒரு பயனர், <strong>Proxmox VE authentication server</strong> (<code>pve</code>) ரியல்மில். இதற்குக் கடவுச்சொல் தேவையில்லை - இது API டோக்கனை மட்டுமே வைத்திருக்கும்.',
            'user_2' => '<strong>Datacenter &rarr; Permissions &rarr; Roles &rarr; Create</strong>: <code>Sys.Audit</code>, <code>VM.Audit</code> மற்றும் <code>Datastore.Audit</code> உடன் <code>FreeITSMSync</code> போன்ற ஒரு பங்கை உருவாக்கவும்; விருந்தினர் IP முகவரிகளுக்கு, Proxmox VE 9-இல் <code>VM.GuestAgent.Audit</code> அல்லது Proxmox VE 8-இல் <code>VM.Monitor</code> ஆகியவற்றையும் சேர்க்கவும் (பதிப்பு 9 அதை மாற்றியது).',
            'user_3' => '<strong>Datacenter &rarr; Permissions &rarr; Add &rarr; User Permission</strong>: பாதை <code>/</code>, அந்தப் பயனர் மற்றும் அந்தப் பங்கு.',
            'token_heading' => '2. API டோக்கன் (பரிந்துரைக்கப்படுகிறது)',
            'token_1' => '<strong>Datacenter &rarr; Permissions &rarr; API Tokens &rarr; Add</strong>: அந்தப் பயனருக்கு, <code>itsm</code> போன்ற Token ID உடன்.',
            'token_2' => 'டோக்கனுக்குப் பயனரின் அனுமதிகள் இருக்க <strong>Privilege Separation</strong> என்பதைத் தேர்வுநீக்கவும் - அல்லது அதைத் தேர்வில் வைத்து, படி 1-இல் உள்ளபடி பங்கை டோக்கனுக்கே வழங்கவும்.',
            'token_3' => 'Proxmox <strong>secret</strong>-ஐ ஒரே ஒருமுறை காட்டும். இப்போதே நகலெடுக்கவும்; தொலைந்தால், டோக்கனை நீக்கி மற்றொன்றை உருவாக்கவும்.',
            'fill_heading' => '3. FreeITSM-இல் சேவையகத்தைச் சேர்க்கவும்',
            'fill_host' => '<strong>சேவையக முகவரி</strong>: <code>https://pve.example.com:8006</code>. https மட்டுமே ஏற்கப்படும், ஏனெனில் ஒவ்வொரு கோரிக்கையுடனும் secret பயணிக்கிறது.',
            'fill_user' => '<strong>பயனர் அல்லது API டோக்கன்</strong>: டோக்கன் ID, <code>freeitsm@pve!itsm</code> - பயனர், ரியல்ம், <code>!</code>, டோக்கன் ID. <code>freeitsm@pve</code> போன்ற சாதாரணப் பயனரும் அதன் கடவுச்சொல்லுடன் வேலை செய்யும்.',
            'fill_secret' => '<strong>கடவுச்சொல்</strong>: டோக்கன் secret (அல்லது பயனரின் கடவுச்சொல்). இது குறியாக்கம் செய்யப்பட்டுச் சேமிக்கப்படும், மீண்டும் காட்டப்படாது; திருத்தும்போது அதை அப்படியே வைத்திருக்க வெறுமையாக விடவும்.',
            'fill_verify' => '<strong>சான்றிதழைச் சரிபார்</strong>: நம்பகமான அதிகார அமைப்பின் சான்றிதழுக்கு இதைத் தேர்வில் வைத்திருக்கவும். Proxmox தனது சொந்த சுய-கையொப்பமிட்ட சான்றிதழுடன் நிறுவப்படுகிறது; அதற்கு இதைத் தேர்வுநீக்கவும், அல்லது இன்னும் சிறந்தது, Proxmox-க்கு நம்பகமான சான்றிதழை வழங்கவும்.',
            'fill_interval' => '<strong>ஒத்திசைவு இடைவெளி</strong>: <code>cron/proxmox_sync.php</code> இயக்கும் திட்டமிட்ட ஒத்திசைவுகளுக்கு இடையிலான நிமிடங்கள்.',
            'test' => '<strong>சோதி</strong> என்பதைக் கிளிக் செய்து, பின்னர் <strong>இப்போது ஒத்திசை</strong> மற்றும் <strong>VMகளைக் காட்டு</strong> என்பதைக் கிளிக் செய்யவும்.',
            'ips_heading' => 'IP முகவரிகள்',
            'ips' => 'QEMU guest agent மூலமாக மட்டுமே Proxmox-க்கு ஒரு VM-இன் IP முகவரி தெரியும்: VM-இன் <strong>Options</strong>-இல் அதை இயக்கி, விருந்தினரில் <code>qemu-guest-agent</code>-ஐ நிறுவவும். VM-இன் சொந்த நெட்வொர்க் கார்டுகளில் உள்ள முகவரிகள் மட்டுமே வைக்கப்படும், எனவே அதற்குள் உள்ள Docker மற்றும் bridge இடைமுகங்கள் தவிர்க்கப்படும். ஒரு கண்டெய்னரின் முகவரி அதன் உள்ளமைவிலிருந்து வரும்; DHCP முகவரி தெரியாது.',
            'removal_heading' => 'ஒரு VM பட்டியலிலிருந்து மறையும்போது',
            'removal' => 'வெற்றிகரமாகப் படிக்கப்பட்ட பட்டியலில் ஒரு VM இல்லாதபோது மட்டுமே அது அகற்றப்படும். ஒரு நோட் ஆஃப்லைனில் இருந்தாலோ, அதன் VM அல்லது கண்டெய்னர் பட்டியலைப் படிக்க முடியாவிட்டாலோ, அதன் VMகள் வைத்திருக்கப்படும். மேலும் FreeITSM அறிந்த VMகளில் பாதிக்குக் குறைவானவையே காணப்பட்டால், ஆரோக்கியமான ஒத்திசைவு உறுதிப்படுத்தும் வரை எதுவுமே அகற்றப்படாது (<strong>பாதுகாப்புக் காவல்</strong>).',
            'trouble_heading' => 'ஏதாவது தவறாக இருக்கும்போது',
            'trouble_401' => '<strong>மறுக்கப்பட்டது (HTTP 401 அல்லது 403)</strong>: டோக்கன் ID அல்லது secret தவறு, அல்லது அதற்கு அனுமதிகள் இல்லை. ரியல்ம் <code>pam</code> அல்ல, <code>pve</code> என்பதைச் சரிபார்க்கவும்.',
            'trouble_reach' => '<strong>Proxmox சேவையகத்தை அடைய முடியவில்லை</strong>: முகவரி அல்லது போர்ட் (பொதுவாக 8006) தவறு, அல்லது ஃபயர்வால் தடையாக உள்ளது.',
            'trouble_cert' => 'சான்றிதழைச் சரிபார் தேர்வில் இருக்கும்போது <strong>சான்றிதழ் பிழை</strong>: Proxmox தனது சுய-கையொப்பமிட்ட சான்றிதழைப் பயன்படுத்துகிறது. அதைத் தேர்வுநீக்கவும், அல்லது Proxmox-இல் நம்பகமான சான்றிதழை நிறுவவும்.',
            'trouble_node' => '<strong>இந்தச் சுழற்சியில் அடைய முடியவில்லை: ஒரு நோட் பெயர்</strong>: அந்த நோட் அல்லது அதன் பட்டியல் பதிலளிக்கவில்லை. அதன் VMகள் வைத்திருக்கப்படும்.',
            'trouble_guard' => '<strong>பாதுகாப்புக் காவல்</strong>: அறியப்பட்ட VMகளில் பாதிக்குக் குறைவானவையே காணப்பட்டன, எதுவும் நீக்கப்படவில்லை. பொதுவாக இது ஓர் அனுமதிப் பிரச்சினை அல்லது ஆஃப்லைன் நோட்; உண்மையான நீக்கம் அல்ல.',
            'more' => 'முழு வழிகாட்டி விக்கியில் உள்ளது: <a href="https://github.com/edmozley/freeitsm/wiki/Proxmox-VE" target="_blank" rel="noopener">Proxmox VE</a>.',
        ],
        'vcloud' => [
            'nav' => 'Cloud Director சேவையகங்கள்',
            'heading' => 'VMware Cloud Director சேவையகங்கள்',
            'intro' => 'FreeITSM ஒன்று அல்லது அதற்கு மேற்பட்ட VMware Cloud Director சேவையகங்களிலிருந்து VMகளை (அவற்றின் நெட்வொர்க் கார்டுகள் மற்றும் டிஸ்க்குகளுடன்) மற்றும் edge gateway-களைப் படித்து, VMகளை <strong>சேவையகங்கள்</strong> பிரிவின் கீழ் பட்டியலிடும். இது படிப்பதை மட்டுமே செய்கிறது. சேவையகங்களை <strong>அமைப்புகள் &rarr; VMware Cloud Director சேவையகங்கள்</strong> என்பதன் கீழ் சேர்க்கவும்.',
            'user_heading' => '1. ஒரு பயனரைத் தேர்ந்தெடுக்கவும்',
            'user_1' => 'ஒரு நிறுவனத்திற்கு (organization): அதில் உள்ள <strong>Organization Administrator</strong> பங்கு கொண்ட பயனர், அல்லது அதன் VMகளையும் நெட்வொர்க்குகளையும் பார்க்கக்கூடிய படிக்க-மட்டும் பங்கு.',
            'user_2' => 'எல்லா நிறுவனங்களுக்கும்: <code>System</code> நிறுவனத்துடன் ஒரு வழங்குநர் நிர்வாகி.',
            'fill_heading' => '2. FreeITSM-இல் சேவையகத்தைச் சேர்க்கவும்',
            'fill_host' => '<strong>சேவையக முகவரி</strong>: <code>https://vcd.example.com</code>, Cloud Director போர்ட்டலின் முகவரி. https மட்டுமே ஏற்கப்படும்.',
            'fill_org' => '<strong>நிறுவனம் (Organization)</strong>: அதன் <em>பெயர்</em> - உள்நுழையும்போது முகவரியில் உள்ளது (<code>/tenant/acme</code> என்றால் <code>acme</code>) - காட்சிப் பெயர் அல்ல. வழங்குநர் நிர்வாகிக்கு <code>System</code>.',
            'fill_user' => '<strong>பயனர்</strong> மற்றும் <strong>கடவுச்சொல்</strong>: படி 1-இல் உள்ள பயனர், <code>@organization</code> இல்லாமல். கடவுச்சொல் குறியாக்கம் செய்யப்பட்டுச் சேமிக்கப்படும், மீண்டும் காட்டப்படாது.',
            'fill_version' => '<strong>API பதிப்பு</strong>: Cloud Director 10.5-க்கு <code>38.0</code>, 10.3-க்கு <code>36.2</code>. சேவையகம் வழங்காத பதிப்பு சோதனையில் தெளிவாகத் தோல்வியடையும்.',
            'fill_verify' => '<strong>சான்றிதழைச் சரிபார்</strong>: போர்ட்டல் சுய-கையொப்பமிட்ட சான்றிதழைப் பயன்படுத்தாவிட்டால் இதைத் தேர்வில் வைத்திருக்கவும்.',
            'test' => '<strong>சோதி</strong> என்பதைக் கிளிக் செய்து, பின்னர் <strong>இப்போது ஒத்திசை</strong> மற்றும் <strong>VMகளைக் காட்டு</strong> என்பதைக் கிளிக் செய்யவும்; இது edge gateway-களையும் பட்டியலிடும்.',
            'removal_heading' => 'ஒரு VM பட்டியலிலிருந்து மறையும்போது',
            'removal' => 'முழு VM பட்டியலும், அதன் ஒவ்வொரு பக்கமும் படிக்கப்பட்ட பிறகு மட்டுமே. ஒரு பக்கம் தோல்வியடைந்தால், அந்தமுறை எதுவும் அகற்றப்படாது. அதே பாதுகாப்புக் காவல் பொருந்தும்: அறியப்பட்ட VMகளில் பாதிக்குக் குறைவானவை காணப்பட்டால் எதுவும் அகற்றப்படாது. Edge gateway-கள் அவற்றின் எல்லாப் பக்கங்களும் படிக்கப்பட்ட பிறகு மட்டுமே அகற்றப்படும்.',
            'trouble_heading' => 'ஏதாவது தவறாக இருக்கும்போது',
            'trouble_401' => '<strong>உள்நுழைவு மறுக்கப்பட்டது (HTTP 401 அல்லது 403)</strong>: பயனர், கடவுச்சொல் அல்லது நிறுவனம் தவறு - பொதுவாக நிறுவனத்தின் பெயருக்குப் பதிலாக அதன் காட்சிப் பெயரைக் கொடுத்திருப்பது.',
            'trouble_reach' => '<strong>vCloud Director சேவையகத்தை அடைய முடியவில்லை</strong>: முகவரி தவறு, அல்லது ஃபயர்வால் தடையாக உள்ளது.',
            'trouble_partial' => '<strong>ஓரளவு மட்டுமே படிக்க முடிந்தது</strong>: VM பட்டியலின் ஒரு பக்கம் தோல்வியடைந்தது. எதுவும் அகற்றப்படவில்லை; அடுத்த ஒத்திசைவு மீண்டும் முயலும்.',
            'trouble_guard' => '<strong>பாதுகாப்புக் காவல்</strong>: அறியப்பட்ட VMகளில் பாதிக்குக் குறைவானவையே காணப்பட்டன, எதுவும் நீக்கப்படவில்லை. பொதுவாக பயனர் உரிமைகளை இழந்திருப்பார், அல்லது நிறுவனம் மாறியிருக்கும்.',
            'more' => 'முழு வழிகாட்டி விக்கியில் உள்ளது: <a href="https://github.com/edmozley/freeitsm/wiki/VMware-Cloud-Director" target="_blank" rel="noopener">VMware Cloud Director</a>.',
        ],
        'companies' => [
            'nav' => 'சொத்துகள் மற்றும் நிறுவனங்கள்',
            'heading' => 'சொத்துகள் மற்றும் நிறுவனங்கள்',
            'intro' => 'ஒன்றுக்கு மேற்பட்ட நிறுவனங்களைக் கவனிக்கும் நிறுவலில், ஒவ்வொரு சொத்தும் அவற்றில் ஒன்றுக்குச் சொந்தமானது. <em>நீங்கள் ஒரே நிறுவனத்திற்காக FreeITSM-ஐ இயக்கினால் இந்தப் பிரிவு பொருந்தாது.</em>',
            'move' => '<strong>சொத்தை நகர்த்துதல்</strong> &mdash; <strong>முக்கிய தகவல்</strong> பிரிவில், சொத்துக் குறிச்சொல்லுக்கு அருகிலுள்ள <strong>நிறுவனம்</strong> புலத்தை மாற்றி உறுதிப்படுத்தவும். நீங்களே அணுகக்கூடிய நிறுவனத்திற்கு மட்டுமே சொத்தை நகர்த்த முடியும், மேலும் நகர்த்தல் அதன் வரலாற்றில் பதிவாகும்.',
            'cleared' => '<strong>எது அழிக்கப்படும்</strong> &mdash; பழைய நிறுவனத்திற்கு மட்டுமே சொந்தமான அனைத்தும்: அதன் இடம் (இடம் பகிரப்பட்டதாக இல்லாவிட்டால்), மற்றும் பழைய நிறுவனம் தனக்காகச் சேர்த்த வகை அல்லது நிலை. நகர்த்தலுக்குப் பிந்தைய செய்தி எது அழிக்கப்பட்டது என்பதைக் குறிப்பிடும். வரலாறு, தனிப்பயன் புலங்கள், ஆவணங்கள் மற்றும் அதை வைத்திருக்கும் பகுப்பாய்வாளர் ஆகிய அனைத்தும் அதனுடன் நகரும்.',
            'refused' => '<strong>நகர்த்தல் மறுக்கப்படும்போது</strong> &mdash; புதிய நிறுவனத்தில் ஏற்கனவே அதே பெயர் அல்லது சொத்துக் குறிச்சொல் கொண்ட சொத்து இருக்கும்போது, அல்லது சொத்து வேறு நிறுவனத்தைச் சேர்ந்த நபரிடம் இருக்கும்போது. எது என்பதை செய்தி சொல்லும், அதனால் நீங்கள் சரிசெய்து மீண்டும் முயலலாம்.',
            'add' => '<strong>சொத்தைச் சேர்த்தல்</strong> &mdash; நீங்கள் ஒன்றுக்கு மேற்பட்ட நிறுவனங்களை அணுகும்போது, <strong>சொத்தைச் சேர்</strong> அது எந்த நிறுவனத்திற்கானது என்று கேட்கும், மேலும் வகை, நிலை மற்றும் இடப் பட்டியல்கள் உங்கள் தேர்வைப் பின்பற்றும். <strong>அனைத்து நிறுவனங்கள்</strong> காட்சியில் இயல்புநிலை எதுவும் இல்லை, எனவே புதிய சொத்து கடைசியாக நீங்கள் தேர்ந்தெடுத்த நிறுவனத்தில் தவறுதலாகச் சேராது.',
            'shared' => '<strong>பகிரப்பட்ட இடங்கள்</strong> &mdash; <strong>அமைப்புகள் &rarr; இடங்கள்</strong> என்பதன் கீழ், எல்லா நிறுவனங்களுக்கும் அணுகல் உள்ளவர், பல வாடிக்கையாளர்கள் பயன்படுத்தும் தரவு மையம் போன்ற இடத்தை <strong>ஒவ்வொரு நிறுவனத்துடனும் பகிரப்பட்டது</strong> எனக் குறிக்கலாம். அப்போது ஒவ்வொரு நிறுவனமும் தனது சொந்த இடங்களுடன் அதையும் தேர்ந்தெடுக்கலாம். மற்ற நிறுவனங்களின் சொத்துகள் இன்னும் அங்கு இருக்கும்போது பகிரப்பட்ட இடத்தின் பகிர்வை நிறுத்த முடியாது.',
            'note' => '<strong>அனைத்து நிறுவனங்கள்</strong> காட்சியிலும்கூட சொத்துப் பட்டியல் ஒரு நேரத்தில் ஒரு நிறுவனத்தை மட்டுமே காட்டும். நகர்த்தப்பட்ட சொத்து நீங்கள் பார்க்கும் பட்டியலிலிருந்து மறையும் &mdash; அதைப் பார்க்க அதன் புதிய நிறுவனத்திற்கு மாறவும்.',
            'recon' => '<strong>வன்பொருள் கண்டறிதல் மற்றும் ஒப்பீடு</strong> &mdash; தானியங்கி இருப்பு அறிக்கைகள் (PowerShell ஏஜென்ட் அல்லது Microsoft Intune-இலிருந்து) இலக்கு நிறுவனத்திற்குள் மட்டுமே சொத்துகளைப் பொருத்தும். வெவ்வேறு நிறுவனங்களில் உள்ள ஒரே வரிசை எண்கள் அல்லது ஹோஸ்ட்பெயர்கள் முழுமையாகத் தனிமைப்படுத்தப்பட்டு எல்லைகளைக் கடக்காது.',
        ],
        'asset_tags' => [
            'nav' => 'தானியங்கி சொத்துக் குறிச்சொற்கள்',
            'heading' => 'தானியங்கி சொத்துக் குறிச்சொற்கள்',
            'intro' => '<strong>அமைப்புகள் &rarr; சொத்துக் குறிச்சொற்கள்</strong> என்பதை இயக்கினால், ஒவ்வொரு புதிய சொத்தும் வரிசையில் அடுத்த குறிச்சொல்லைப் பெறும் - கையால் சேர்த்தாலும், REST API வழியாக, விரிதாள் இறக்குமதியிலிருந்து, இருப்பு ஏஜென்ட் அல்லது Intune மூலம் சேர்த்தாலும். கையால் உள்ளிட்ட குறிச்சொல் எப்போதும் வைத்திருக்கப்படும். நீங்கள் இயக்கும் வரை அணைந்திருக்கும்.',
            'monotonic_strong' => 'வடிவம்',
            'monotonic_text' => 'ஒரு வரி, டிக்கெட் எண்ணிடலில் உள்ள அதே டோக்கன்கள்: <code>AST-{#####}</code>, <code>{COMPANY}-LT-{####}</code>, <code>IT{YY}-{######}</code>. # எண்ணிக்கை என்பது குறைந்தபட்ச இலக்கங்கள், ஒருபோதும் வரம்பு அல்ல. எல்லாவற்றையும் சேர்த்து ஒருமுறை எண்ணுவதைத் தேர்ந்தெடுக்காவிட்டால், ஒவ்வொரு நிறுவனமும் தனியாக எண்ணும்.',
            'lifecycle_strong' => 'எண்கள் மீண்டும் பயன்படுத்தப்படாது',
            'lifecycle_text' => 'ஒரு குறிச்சொல் ஸ்டிக்கர், விலைப்பட்டியல் மற்றும் விரிதாளில் சென்றடையும், எனவே ஒருமுறை வழங்கிய எண் மீண்டும் வழங்கப்படாது - சொத்து நீக்கப்பட்ட பிறகும் இல்லை, கவுன்டரை நகர்த்தினாலும் இல்லை. அதை முன்னோக்கி நகர்த்தலாம், பின்னோக்கி அல்ல. சொத்திலேயே குறிச்சொல்லை மாற்றலாம், அந்த மாற்றம் அதன் வரலாற்றில் இருக்கும்; QR குறியீடு தொடர்ந்து வேலை செய்யும், ஏனெனில் அதில் குறிச்சொல் ஒருபோதும் இருக்கவில்லை.',
        ],
        'asset_labels' => [
            'nav' => 'பௌதீக சொத்து லேபிள்கள் &amp; QR தனிப்பயனாக்கம்',
            'heading' => 'பௌதீக சொத்து லேபிள்கள் மற்றும் QR தனிப்பயனாக்கம்',
            'intro' => 'சொத்து லேபிள்களை A4 தாள்களில் அல்லது லேபிள் பிரிண்டரின் டேப் அல்லது ரோல்களில், லேபிளின் சரியான அளவில் PDF ஆக அச்சிடுங்கள் - அல்லது தொழில்முறை அச்சகத்துக்குச் சொத்துத் தரவை ஏற்றுமதி செய்யுங்கள்.',
            'fields_strong' => 'அமைக்கக்கூடிய புலத் தேர்வு',
            'fields_text' => '<strong>அமைப்புகள் &rarr; சொத்து லேபிள்கள் &amp; QR</strong> என்பதன் கீழ், எந்தப் புலங்கள் எந்த வரிசையில் தோன்ற வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும் - ஹோஸ்ட்பெயர், வரிசை எண், மாதிரி, இடம், நிதி ID போன்ற உங்கள் சொந்த தனிப்பயன் புலங்கள் - மேலும் தலைப்பு, அடிக்குறிப்பு, ஒவ்வொரு புலத்தின் பெயரையும் அச்சிட வேண்டுமா என்பதையும். சொத்துக் குறிச்சொல் எப்போதும் லேபிளில் இருக்கும்.',
            'qr_strong' => 'QR குறியீடு மற்றும் லோகோ',
            'qr_text' => 'QR குறியீடு, நிறுவலின் பொது முகவரியைப் பயன்படுத்தி FreeITSM-இல் சொத்தைத் திறக்கும். அதன் நடுவில் உங்கள் லோகோவை வைக்கலாம்; அப்போது குறியீடு கூடுதல் உள்ளமைந்த மிகைப்புடன் அச்சிடப்படும், அதனால் அது தொடர்ந்து ஸ்கேன் ஆகும். தொகுப்பை அச்சிடுமுன் ஒன்றைச் சிறிய அளவில் அச்சிட்டு, சாதாரண ஃபோனில் ஸ்கேன் செய்து பாருங்கள்.',
            'designs_strong' => 'லேபிள் வடிவமைப்புகள்',
            'designs_text' => '<strong>அமைப்புகள் &rarr; சொத்து லேபிள்கள் &amp; QR &rarr; லேபிள் வடிவமைப்புகள்</strong> என்பதில் பல வடிவமைப்புகளை வைத்திருக்கலாம் - ஒவ்வொன்றும் ஒரு லேபிள் அளவில் ஓர் அமைப்பு - <strong>லேபிளை அச்சிடு</strong> பயன்படுத்துவதைத் தேர்ந்தெடுக்கலாம். அமைப்புகள்: <em>Standard</em> (லேபிள் எப்போதும் இருந்தது போல), <em>Logo left, details middle, QR right</em> (உங்கள் லோகோ பெரிதாக, டேப் லேபிள்களுக்கு), <em>Small</em> (QR மற்றும் குறிச்சொல்) மற்றும் <em>Large</em> (லோகோ, QR, பின்னர் விவரங்கள்). அவை தாவலில் கீழே அமைக்கப்பட்ட தலைப்பு, அடிக்குறிப்பு, புலங்கள் மற்றும் லோகோவைப் பயன்படுத்தும். அச்சுப் பக்கத்தில் ஒரு அச்சுக்கு வேறொரு வடிவமைப்பு அல்லது அளவைத் தேர்ந்தெடுக்கலாம்.',
            'designer_strong' => 'லேபிள் வடிவமைப்பாளர்',
            'designer_text' => 'ஒரு ஸ்லைடைப் போல லேபிளை நீங்களே அமைக்க ஒரு வடிவமைப்புக்கு அருகில் உள்ள <strong>வடிவமை</strong> என்பதை அழுத்தவும்: கருவிப்பெட்டியிலிருந்து உரை, புலங்கள், புலப் பட்டியல், QR குறியீடு, உங்கள் லோகோ, கோடுகள் மற்றும் பெட்டிகளை இழுக்கவும், பிறகு அவற்றை நகர்த்தி அளவு மாற்றவும் - அவை லேபிளின் விளிம்புகள், மையம் மற்றும் ஒன்றோடொன்று ஒட்டிக்கொள்ளும். லேபிள் உண்மையான சொத்தின் மதிப்புகளைக் காட்டுகிறது, <em>நீளமான மதிப்புகளுடன் மாதிரி</em> மிக மோசமான நிலையைக் காட்டுகிறது; ஒவ்வொரு உரையும் நீளமான மதிப்பு சுருங்க வேண்டுமா, சுற்ற வேண்டுமா அல்லது வெட்டப்பட வேண்டுமா என்று தேர்ந்தெடுக்கிறது. ஒழுங்கமை பொருட்களை வரிசைப்படுத்தும், அம்புக்குறி விசைகள் சற்று நகர்த்தும், Ctrl+Z செயல்தவிர்க்கும். வடிவமைப்பாளரில் சேமித்தவுடன், வடிவமைப்பு நீங்கள் அமைத்ததை அப்படியே வைத்திருக்கும், தாவலில் கீழே அமைக்கப்பட்ட தலைப்பு, அடிக்குறிப்பு மற்றும் புலங்களை இனி பின்பற்றாது.',
            'sizes_strong' => 'லேபிள் அளவுகள் மற்றும் அச்சிடுதல்',
            'sizes_text' => 'Brother TZe மற்றும் DK டேப்கள், Dymo லேபிள்கள், நான்கு A4 தாள்கள் அல்லது உங்கள் சொந்த அளவு. <strong>பதிவிறக்கு</strong> லேபிளின் சரியான அளவில் PDF உருவாக்கும் - டேப் அல்லது ரோல் பிரிண்டருக்கு ஒரு பக்கத்துக்கு ஒரு லேபிள். அதை பிரிண்டரின் சொந்த டிரைவர் மூலம் <strong>Actual size</strong>-இல் அச்சிடுங்கள் (ஒருபோதும் "Fit to page" அல்ல). தாளுக்கு, உங்கள் லேபிள்கள் சற்று சீரற்று அச்சானால், 10 மிமீ வரையிலான பிரிண்டர் ஆஃப்செட் ஒவ்வொரு லேபிளையும் நகர்த்தும். டேப் அல்லது ரோல் பிரிண்டருக்கான வடிவமைப்பு திடமான கருப்பில் அச்சாகும் - உரை, கோடுகள் மற்றும் கருப்பு-வெள்ளை லோகோ - ஏனெனில் அந்தப் பிரிண்டர்கள் சாம்பல் நிறத்தைப் படிக்கக் கடினமான புள்ளிகளாக அச்சிடுகின்றன. நிற லேபிள்களுக்கு வடிவமைப்பில் <strong>கருப்பு-மட்டும் பிரிண்டர்</strong> என்பதைத் தேர்வுநீக்கவும்.',
            'fonts_strong' => 'எழுத்துருக்கள் மற்றும் பிற மொழிகள்',
            'fonts_text' => 'லேபிள்கள் Noto Sans-ஐப் பயன்படுத்துகின்றன, அதில் இல்லாத எழுத்தை கணினியின் சொந்த எழுத்துருக்கள் வரையும், எனவே எந்த மொழியிலும் பெயர்கள் அச்சாகும். <strong>லேபிள் எழுத்துருக்கள்</strong> என்பதன் கீழ் ஓர் எழுத்துருவைப் பதிவேற்றி - உங்கள் பிராண்ட் எழுத்துரு, அல்லது ஒரு மொழிக்கானது - வடிவமைப்பில் தேர்ந்தெடுங்கள். ஒரு வடிவமைப்பு பயன்படுத்தும் எழுத்துருவை நீக்க முடியாது.',
        ],
        'reconciliation' => [
            'nav' => 'கண்டறிதல் &amp; ஒப்பீடு',
            'heading' => 'கண்டறிதல் மற்றும் ஒப்பீடு',
            'intro' => 'ஒரு கணினி (இருப்பு ஏஜென்ட் அல்லது Microsoft Intune-இலிருந்து) அறிக்கை அளிக்கும்போது, அது எந்தச் சொத்து என்பதை FreeITSM முதலில் வரிசை எண்ணாலும் இரண்டாவதாகப் பெயராலும் கண்டறியும், எனவே பெயர் மாற்றப்பட்ட கணினியும் அதே சொத்தாகவே இருக்கும்.',
            'renames_strong' => 'பெயர் மாற்றப்பட்ட கணினி',
            'renames_text' => 'அதன் வரிசை எண் ஏற்கனவே உள்ள சொத்தைக் கண்டறியும்; அது புதிய பெயரை ஏற்கும் - மாற்றம் அதன் வரலாற்றில் இருக்கும் - மேலும் அதன் வைத்திருப்பவர், டிக்கெட்டுகள், ஒப்பந்தங்கள் மற்றும் மென்பொருளை வைத்திருக்கும். முன்பு, பெயர் மாற்றம் இரண்டாவது சொத்தாக வந்தது.',
            'ignored_strong' => 'பொருளற்ற வரிசை எண்கள்',
            'ignored_text' => 'சில இயந்திரங்கள் <em>To be filled by O.E.M.</em> போன்ற இடப்பிடிப்பைத் தெரிவிக்கும். அவை புறக்கணிக்கப்பட்டு, பெயர் பயன்படுத்தப்படும். பட்டியல் <strong>அமைப்புகள் &rarr; கண்டறிதல் &amp; ஒப்பீடு</strong> என்பதன் கீழ் உள்ளது. இரண்டு சொத்துகள் ஒரே உண்மையான வரிசை எண்ணைப் பகிர்ந்தால், FreeITSM அவற்றுக்கிடையே ஊகிக்காது.',
            'refresh_strong' => 'பழைய பெயருடன் மாற்றுச் சாதனம்',
            'refresh_text' => 'புதிய லேப்டாப்பிற்குப் பெரும்பாலும் பழையதன் பெயர் கொடுக்கப்படும். அதன் வரிசை எண் வேறுபட்டதால், அது பழைய பதிவைக் கைப்பற்றாமல் புதிய சொத்தாகும் - மேலும் எந்தச் சொத்து இன்னும் அந்தப் பெயரைக் கொண்டுள்ளது என்பதை அதன் வரலாறு குறிப்பிடும், அதனால் பழையதன் பெயரை மாற்றலாம் அல்லது ஓய்வு அளிக்கலாம்.',
            'intune_strong' => 'Intune',
            'intune_text' => 'Intune ஒரு சொத்துடன் இணைத்த சாதனம், சொத்தை வேறொரு நிறுவனத்துக்கு நகர்த்திய பிறகும் இணைந்தே இருக்கும். புதிய சொத்து உருவாக்கப்படும் முன், புதிய சாதனங்கள் வரிசை எண், பின்னர் பெயர் மூலம் பொருத்தப்படும். <strong>System &rarr; Integrations &rarr; Microsoft 365 &rarr; Intune</strong> புதிய சாதனங்கள் எந்த நிறுவனத்தில் பொருத்தப்பட்டு உருவாக்கப்படும் என்பதையும், Intune-இல் சாதனம் மறுபெயரிடப்படும்போது சொத்து மறுபெயரிடப்பட வேண்டுமா என்பதையும் தேர்ந்தெடுக்கிறது - மேம்படுத்திய பின் அணைந்திருக்கும், எனவே நீங்கள் தேர்ந்தெடுக்கும் வரை எதுவும் மறுபெயரிடப்படாது.',
            'intune_holder_strong' => 'Intune-இலிருந்து வைத்திருப்பவர்கள்',
            'intune_holder_text' => '<strong>System &rarr; Integrations &rarr; Microsoft 365 &rarr; Intune</strong> யாரும் வைத்திருக்காத ஒவ்வொரு சொத்தையும் அதன் சாதனத்தின் முதன்மைப் பயனருக்கு ஒதுக்கவும் முடியும், நபர்கள் Microsoft Entra ID-இலிருந்து இறக்குமதி செய்யப்பட்டதும் Entra object id மூலம் சரியாகப் பொருத்தப்படும். ஏற்கனவே வைத்திருப்பவர் உள்ள சொத்து ஒருபோதும் மாற்றப்படாது, நீங்கள் இயக்கும் வரை இது அணைந்திருக்கும்.',
            'intune_holder_when' => 'இது ஒவ்வொரு Intune ஒத்திசைவுக்குப் பின்னும் ஒவ்வொரு Entra இறக்குமதிக்குப் பின்னும் இயங்கும், எனவே இரண்டில் எது முதலில் இயங்குகிறது என்பது முக்கியமல்ல.',
            'companies_strong' => 'பல நிறுவனங்கள்',
            'companies_text' => 'இருப்பு ஏஜென்ட் தனது விசையின் நிறுவனத்திற்குள் மட்டுமே பொருத்தும், எனவே ஒரே கணினிப் பெயர் அல்லது வரிசை எண் கொண்ட இரண்டு நிறுவனங்கள் ஒருபோதும் குழம்பாது.',
        ],
        'page_title' => 'சொத்து மேலாண்மை வழிகாட்டி',
        'guide' => 'வழிகாட்டி',
        'hero_title' => 'சொத்து மேலாண்மை வழிகாட்டி',
        'hero_subtitle' => 'உங்கள் எஸ்டேட்டில் உள்ள ஒவ்வொரு சாதனத்தையும் கண்டறிந்து, கண்காணித்து, நிர்வகிக்கவும் &mdash; லேப்டாப்புகள் முதல் சேவையகங்கள் வரை.',
        'cf_page_title' => 'எதையும் பதிவு செய்தல்',
        'cf_guide' => 'வழிகாட்டி',
        'cf_hero_title' => 'எதையும் பதிவு செய்தல், அதை இறக்குமதி செய்தல்',
        'cf_hero_subtitle' => 'பிரிண்டர்கள், மானிட்டர்கள், ஹெட்செட்டுகள், தொலைக்காட்சிகள் &mdash; நீங்கள் கண்காணிக்க வேண்டியது எதுவாக இருந்தாலும், உங்களுக்கு முக்கியமான விவரங்களுடன்.',
        'cf_nav_why' => 'இது ஏன் உள்ளது',
        'cf_nav_idea' => 'புலங்கள், தொகுப்புகள் மற்றும் வகைகள்',
        'cf_nav_making' => 'புலத்தை உருவாக்குதல்',
        'cf_nav_sets' => 'தொகுப்புகளால் புலங்களை மீண்டும் பயன்படுத்துதல்',
        'cf_nav_one_asset' => 'ஒரே சொத்துக்கான புலங்கள்',
        'cf_nav_adding' => 'சொத்தைக் கையால் சேர்த்தல்',
        'cf_nav_import' => 'விரிதாளை இறக்குமதி செய்தல்',
        'cf_nav_matching' => 'ஒரு வரிசையை எது அடையாளப்படுத்துகிறது',
        'cf_nav_attention' => 'கவனம் தேவைப்படும் வரிசைகள்',
        'cf_nav_using' => 'மதிப்புகள் எங்கே தோன்றும்',
        'cf_nav_gotchas' => 'தெரிந்துகொள்ள வேண்டியவை',
        'cf_link' => 'எதையும் பதிவு செய்தல் (பிரிண்டர்கள், தொலைக்காட்சிகள், ஹெட்செட்டுகள்) &amp; இறக்குமதி',
        'overview_cf_lead' => 'கணினி அல்லாத ஒன்றைக் கண்காணிக்கிறீர்களா?',
        'overview_cf_body' => 'பிரிண்டர்கள், மானிட்டர்கள், ஹெட்செட்டுகள் மற்றும் தொலைக்காட்சிகள் இருப்பு ஸ்கிரிப்டை இயக்குவதில்லை, எனவே கீழே உள்ள விவரங்கள் அவற்றுக்கு இல்லை. அவற்றைக் கையால் சேர்க்கலாம் அல்லது விரிதாளை இறக்குமதி செய்யலாம், மேலும் ஒவ்வொரு வகைச் சொத்துக்கும் உங்களுக்கு முக்கியமான விவரங்களைப் பதிவு செய்யலாம் &mdash; அதற்கெல்லாம் தனி வழிகாட்டி உள்ளது.',
        'nav_overview' => 'மேலோட்டம்',
        'nav_asset_detail' => 'சொத்து விவரக் காட்சி',
        'nav_table_view' => 'அட்டவணைக் காட்சி',
        'nav_inventory_script' => 'சரக்கு ஸ்கிரிப்ட்',
        'nav_what_collected' => 'என்ன சேகரிக்கப்படுகிறது',
        'nav_deployment' => 'அளவில் வரிசைப்படுத்துதல்',
        'nav_servers' => 'சேவையகங்கள் & vCenter',
        'nav_dashboard' => 'டாஷ்போர்டு',
        'nav_users' => 'யாரிடம் எது உள்ளது',
        'nav_tips' => 'விரைவு குறிப்புகள்',
        'users_heading' => 'யாரிடம் எது உள்ளது',
        'users_intro' => '<strong>பயனர்கள்</strong> தத்தல், சொத்துப் பட்டியலில் ஒவ்வொன்றாகத் தேட வேண்டிய ஒரு கேள்விக்குப் பதிலளிக்கிறது: இந்த நபரிடம் உண்மையில் என்ன உள்ளது? ஒருவரைத் தேர்ந்தெடுத்தால், அவருக்கு ஒதுக்கப்பட்ட அனைத்தையும் ஒரே திரையில் காண்பீர்கள், மேலும் அவர் கையொப்பமிட ஒப்படைப்பு ஆவணத்தை அச்சிடலாம்.',
        'users_step1_strong' => 'நபரைக் கண்டறியவும்.',
        'users_step1_list' => 'இடதுபுறப் பட்டியல் உங்கள் தற்போதைய நபர்களை, ஒவ்வொருவரும் வைத்திருப்பதன் எண்ணிக்கையுடன் காட்டும். பெயர், மின்னஞ்சல் அல்லது துறை மூலம் தேடுங்கள், மேலும் <strong>பணி விலகியவர்கள்</strong>, <strong>அனைவரும்</strong> அல்லது <strong>உபகரணம் வைத்திருப்பவர்கள்</strong> மட்டும் என்பதற்கு முதல் கீழ்விரியைப் பயன்படுத்தவும். நபர்கள் ஒரு டைரக்டரி அல்லது முகவரிப் புத்தகத்திலிருந்து வரும் இடத்தில், இரண்டாவது கீழ்விரியான <strong>மூலம்</strong>, அவற்றில் ஒன்றிலிருந்து வந்தவர்களை மட்டும், அல்லது FreeITSM-இல் சேர்க்கப்பட்டவர்களை மட்டும் பட்டியலிடும்; அவர்களின் விவரங்கள் அவர்கள் எங்கிருந்து வருகிறார்கள் என்பதைக் குறிப்பிடும். எந்த முகவரிப் புத்தகத்திலும் இல்லாத ஒருவரை, அந்த முகவரிப் புத்தகத்திற்கு நிர்வாகி அனுமதித்திருந்தால், <strong>முகவரிப் புத்தகத்தில் சேர்</strong> மூலம் அதில் சேர்க்கலாம்.',
        'users_step2_strong' => 'அவர்கள் வைத்திருப்பதைப் பாருங்கள்.',
        'users_step2_text' => 'ஒருவரைக் கிளிக் செய்தால், அவருக்கு ஒதுக்கப்பட்ட ஒவ்வொரு உருப்படியும் அதன் வகை, பெயர், தயாரிப்பு மற்றும் மாதிரி, வரிசை எண், சொத்துக் குறிச்சொல் மற்றும் ஒதுக்கப்பட்ட தேதியுடன் காட்டப்படும் &mdash; தணிக்கை அல்லது பணி விலகல் சரிபார்ப்புக்கு உண்மையில் தேவைப்படுவது இதுவே.',
        'users_step3_strong' => 'ஒப்படைப்பு ஆவணத்தை அச்சிடுங்கள் அல்லது மின்னஞ்சல் செய்யுங்கள்.',
        'users_step3_text' => '<strong>ஒப்படைப்பு ஆவணம்</strong> பொத்தான், நபர், அவரது உபகரணம் மற்றும் ஒதுக்கீட்டுத் தேதிகளைப் பட்டியலிடும் பதிவை உருவாக்கும்; அதில் ஓர் உறுதிமொழியும், அவர் மற்றும் IT இருவரும் கையொப்பமிட இடமும் இருக்கும். அதை அச்சிடலாம், மின்னணு நகலுக்கு உங்கள் உலாவியின் <strong>PDF ஆகச் சேமி</strong> என்பதைப் பயன்படுத்தலாம், அல்லது நபருக்கு நேரடியாக அனுப்ப <strong>அவருக்கு மின்னஞ்சல்</strong> என்பதைப் பயன்படுத்தலாம். <strong>கணினி &rarr; பிராண்டிங்</strong> என்பதன் கீழ் உங்கள் நிறுவன லோகோவை அமைத்திருந்தால் அது இதில் தோன்றும்.',
        'users_step4_strong' => 'ஆவணம் சொல்வதை மாற்றுங்கள்.',
        'users_step4_text' => '<strong>அமைப்புகள் &rarr; ஒப்படைப்பு ஆவணம்</strong> அதை வடிவமைக்க அனுமதிக்கும்: பிரிவுகளை இயக்கவும் அணைக்கவும், மறுவரிசைப்படுத்தவும், சொற்களை மாற்றவும், உபகரண அட்டவணை எந்த நெடுவரிசைகளைக் காட்ட வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும் &mdash; உங்கள் சொந்த தனிப்பயன் புலங்கள் உட்பட, அதனால் மானிட்டருக்கு அதன் அளவும் தெளிவுத்திறனும் ஆவணத்தில் இருக்கும்படி கையொப்பம் பெறலாம். ஒப்படைப்பு என்பது ஒருவர் கையொப்பமிடும் பதிவு என்பதால், தனிப்பயன் நெடுவரிசைகள் நீங்கள் இயக்கும் வரை அணைந்திருக்கும். <code>{{employee.name}}</code> போன்ற இணைப்புக் குறியீடுகள் ஆவணம் உருவாக்கப்படும்போது தாமாகவே நிரப்பப்படும், மேலும் நீங்கள் தட்டச்சு செய்யும்போது நேரடி முன்னோட்டம் முடிவைக் காட்டும்.',
        'users_step5_strong' => 'அவர்களின் விவரங்களைப் புதுப்பித்து வையுங்கள்.',
        'users_step5_text' => '<strong>திருத்து</strong> நபர் திருத்தியைத் திறக்கும் &mdash; டிக்கெட்டுகள் &rarr; பயனர்கள் திறப்பதும் இதுவே, எனவே பெயர், தொடர்பு விவரங்கள், நிறுவனம், மேலாளர் மற்றும் கடவுச்சொல் ஆகியவை நீங்கள் எங்கிருந்தாலும் ஒரே வழியில் மாற்றப்படும். மேலாளருக்கு, அவரைக் கண்டறிய பெயரின் ஒரு பகுதியைத் தட்டச்சு செய்யவும். <strong>விலகியவராகக் குறி</strong> நபரையும் அவர் வைத்திருந்த அனைத்தையும் பதிவில் வைத்தபடி தற்போதைய பட்டியலிலிருந்து நீக்கும்; <strong>மீண்டும் செயல்படுத்து</strong> அவரைத் திரும்பக் கொண்டுவரும். நபர் டைரக்டரி அல்லது முகவரிப் புத்தகத்திலிருந்து வரும் இடத்தில், அது உரிமை கொண்டுள்ள விவரங்கள் சாம்பல் நிறத்தில் இருக்கும்.',
        'users_managers' => '<strong>மேலாளர்கள்.</strong> ஒருவர் நபர்களை நிர்வகிக்கும் இடத்தில், அவரது விவரங்கள் அவருக்குக் கீழ் யார் பணிபுரிகிறார்கள் என்பதைப் பட்டியலிடும். <strong>மேலாளர் அணுகல்</strong> முழுத்திரைப் பக்கத்தைத் திறக்கும்; அது சுய-சேவை போர்ட்டலில் அந்த நபர் யாருடைய டிக்கெட்டுகளைப் பார்க்கலாம் என்பதை விவரிக்கும், மேலும் நபர்கள், குழுக்கள் அல்லது துறைகளை அவரது குழுவில் சேர்க்க அல்லது விலக்க அனுமதிக்கும்; அவர் பார்க்கக்கூடிய எவரையும் கிளிக் செய்தால் ஏன் என்று தெரியும். நிர்வாகி <strong>கணினி &rarr; மேலாளர்கள்</strong> என்பதன் கீழ் மேலாளர்களை இயக்கிய பிறகு மட்டுமே இது செயல்படும்.',
        'users_tip' => 'உபகரணம் சொத்திலேயே ஒரு நபருக்கு ஒதுக்கப்படுகிறது, எனவே இந்தப் பட்டியலில் ஒருவர் காணாமல் இருந்தால் அல்லது ஒரு உருப்படி தவறாகத் தெரிந்தால், சொத்தைத் திறந்து அதன் ஒதுக்கப்பட்ட பயனரைச் சரிபார்க்கவும்.',
        'overview_intro' => 'சொத்து மேலாண்மை உங்கள் IT எஸ்டேட்டின் முழுமையான சரக்கை வழங்குகிறது. Windows இயந்திரங்கள் PowerShell ஸ்கிரிப்டைப் பயன்படுத்தி தானாகவே அறிக்கையிடுகின்றன, மேலும் VMware மெய்நிகர் இயந்திரங்கள் vCenter இலிருந்து ஒத்திசைகின்றன. அனைத்தும் ஒரே இடத்தில் வந்து சேர்கின்றன, அங்கு நீங்கள் தேடலாம், பயனர்களை ஒதுக்கலாம், மற்றும் டாஷ்போர்டுகளை உருவாக்கலாம்.',
        'card_assets_title' => 'சொத்துகள்',
        'card_assets_desc' => 'கண்டறியப்பட்ட ஒவ்வொரு இயந்திரத்தையும் உலாவி தேடுங்கள். அதன் வன்பொருள், சேமிப்பகம், சாதனங்கள் மற்றும் நிறுவப்பட்ட மென்பொருளை ஒரே பார்வையில் காண எந்த சொத்தையும் கிளிக் செய்யவும்.',
        'card_dashboard_title' => 'டாஷ்போர்டு',
        'card_dashboard_desc' => '13+ வரைபட வகைகளிலிருந்து உங்கள் சொந்த டாஷ்போர்டை உருவாக்குங்கள் &mdash; OS விநியோகம், உற்பத்தியாளர் பிரிப்பு, நினைவக அடுக்குகள் மற்றும் பல. ஒவ்வொரு பகுப்பாய்வாளருக்கும் அவரவர் சொந்த தளவமைப்பு உள்ளது.',
        'card_servers_title' => 'சேவையகங்கள்',
        'card_servers_desc' => 'VMware vCenter உடன் இணைத்து உங்கள் முழு மெய்நிகர் எஸ்டேட்டையும் ஒத்திசைக்கவும். VM விவரங்கள், ஹோஸ்ட் இடம், சேமிப்பகம் மற்றும் நெட்வொர்க் கட்டமைப்பைக் காண்க.',
        'card_assignment_title' => 'பயனர் ஒதுக்கீடு',
        'card_assignment_desc' => 'எந்த சாதனம் யாரிடம் உள்ளது என்பதை நீங்கள் எப்போதும் அறிய சொத்துகளுக்கு பயனர்களை ஒதுக்கவும். மறு ஒதுக்கீடுகள் தணிக்கைத் தடத்தில் பதிவு செய்யப்படுகின்றன.',
        'locations_lead' => 'இடங்கள் எங்கே?',
        'locations_body' => 'படிவங்கள் (காலப்போக்கில் நபர்கள் மற்றும் டிக்கெட்டுகளும்) சொத்துகளுடன் சேர்த்து இடங்களையும் பயன்படுத்துவதால், இடங்கள் இப்போது <strong>System &rarr; Locations</strong> என்பதில் வைக்கப்படுகின்றன. அது அதே பட்டியல், ஒவ்வொரு சொத்தும் தன் இடத்தை வைத்திருக்கிறது. இங்குள்ள <strong>அமைப்புகள் &rarr; இடங்கள்</strong> இன்னும் அதே மரத்தைக் காட்டித் திருத்துகிறது, எனவே நிர்வாகிகள் அல்லாத சொத்து மேலாளர்கள் முன்பு போலவே அதைப் பராமரிக்கலாம் - இரண்டில் ஒரு இடத்தில் மாற்றினால் இரண்டிலும் தெரியும்.',
        'inventory_script_heading' => 'சரக்கு ஸ்கிரிப்ட்',
    ],
    'leases' => [
        'settings_tab' => 'குத்தகை',
        'outcomes_heading' => 'குத்தகை விளைவுகள்',
        'outcomes_intro' => 'குத்தகைக்கு எடுக்கப்பட்ட சொத்துக்கு என்ன நிகழலாம் என்பது. "இன்னும் குத்தகையில்" விளைவுகள் திரும்ப வேண்டியவை எண்ணிக்கையில் சேரும்; "முடிந்தது" விளைவுகள் சேராது. அனைத்து நிறுவனங்களுக்கும் ஒரே பட்டியல்.',
