        'intro' => 'தங்கள் வகை எதிர்பார்க்கும் தகவல் இன்னும் இல்லாத சொத்துகள். இங்குள்ள எதுவும் ஒரு சொத்தைச் சேமிப்பதையோ புதுப்பிப்பதையோ தடுக்காது - எங்கிருந்தாவது ஒரு புலத்தை நிரப்பினால் அது இந்தப் பட்டியலிலிருந்து நீங்கிவிடும். பொருந்தாது என்பது ஒரு சொத்துக்கு ஒரு புலத்தை ஒதுக்கி வைக்கும்; அதை சொத்தில் மீண்டும் மாற்றலாம்.',
        'needs_verify' => 'எதிர்பார்க்கப்படும் தகவலைப் பயன்படுத்தத் தொடங்க Database Verification-ஐ இயக்கவும் (System -> Database Verification).',
