        'count' => '{assets} சொத்துகள், நிரப்ப வேண்டிய {fields} புலங்கள்',
        'none_missing' => 'எதுவும் விடுபடவில்லை - ஒவ்வொரு சொத்திலும் அதன் வகை எதிர்பார்ப்பது உள்ளது.',
        'nothing_expected' => 'எந்தச் சொத்து வகையும் இன்னும் எதையும் எதிர்பார்க்கவில்லை. Settings -> Asset types -> ஒரு வகை -> Expected information என்பதன் கீழ் புலங்களைத் தேர்ந்தெடுக்கவும்.',
        'col_asset' => 'சொத்து',
        'col_type' => 'வகை',
        'col_missing' => 'விடுபட்டது',
        'not_applicable' => 'பொருந்தாது',
        'not_applicable_tip' => 'இந்தப் புலம் இந்தச் சொத்துக்குப் பொருந்தாது. புலத்தில் எதுவும் எழுதப்படாது; இதை சொத்தில் மீண்டும் மாற்றலாம்.',
