        'undo' => 'செயல்தவிர்',
        'undo_tip' => 'இந்தச் சொத்தில் இந்தப் புலத்தை மீண்டும் எதிர்பார்',
        'expected_heading' => 'எதிர்பார்க்கப்படும் தகவல்',
        'expected_intro' => 'இந்த வகைச் சொத்துகளில் இறுதியில் நிரப்பப்பட்டிருக்க வேண்டிய புலங்கள். ஒன்று விடுபட்ட சொத்து வழக்கம்போல் சேமிக்கப்பட்டு புதுப்பிக்கப்படும் - யாராவது அந்தப் புலத்தை நிரப்பும் வரை அல்லது பொருந்தாது எனக் குறிக்கும் வரை அது விடுபட்ட தகவல் என்பதன் கீழ் பட்டியலிடப்படும்.',
        'expected_hint' => 'மேலே உள்ள அமைப்பில் ஒரு பிரிவை மறைப்பதால் அதன் புலங்கள் பொருந்தாதவை ஆகாது.',
