        'set_type_restore' => 'மீட்டெடு',
        'set_fields_link' => 'ஒவ்வொரு வகைக்கான புலங்கள்: System → Custom fields → Consumables.',
        'set_notify' => 'இருப்பு குறையும்போது இவர்களுக்குத் தெரிவி',
        'set_notify_hint' => 'ஒரு உருப்படி அதன் மறுஆர்டர் அளவுக்குக் குறையும் ஒவ்வொரு முறையும் அவர்களுக்கு ஒரு பெல் அறிவிப்பு கிடைக்கும்; மீண்டும் இருப்பு நிரப்பப்பட்டு மறுபடி குறைந்த பின்னரே மீண்டும் கிடைக்கும். தொடக்கத்தில் யாரும் தேர்ந்தெடுக்கப்படவில்லை.',
        'set_reorder' => 'மறுஆர்டர் படிவம்',
        'set_reorder_hint' => 'ஒரு உருப்படியில் மறுஆர்டர் இந்தப் படிவத்தைத் திறக்கும்; அது கீழே உள்ள பதில்களுடன் நிரப்பப்பட்டிருக்கும். பின்னர் அது படிவத்தின் சொந்த ஒப்புதல்கள் வழியாகச் செல்லும்.',
        'set_reorder_none' => 'மறுஆர்டர் பொத்தான் இல்லை',
        'set_reorder_map' => 'எந்தக் கேள்விக்கு எது',
        'set_map_item' => 'உருப்படி',
        'set_map_part_number' => 'அதன் பாகம் எண்',
        'set_map_supplier' => 'அதன் வழங்குநர்',
        'set_map_quantity' => 'பரிந்துரைக்கப்பட்ட அளவு',
        'set_map_unit_cost' => 'அதன் அலகு விலை',
        'set_map_note' => 'மீதமுள்ளதன் குறிப்பு',
        'set_map_skip' => '(பயன்படுத்தப்படவில்லை)',
        'set_saved' => 'சேமிக்கப்பட்டது',
        'deliveries' => 'டெலிவரிகள்',
        'deliveries_intro' => 'ஒரு டெலிவரி என்பது ஒரு ஆர்டர்: அதன் வழங்குநர், ஆர்டர் எண், இன்வாய்ஸ் மற்றும் ஆவணங்கள், ஒவ்வொரு உருப்படிக்கும் ஒரு வரியுடன். அதைப் பதிவு செய்வது ஒவ்வொரு வரியையும் இருப்பில் சேர்க்கும்.',
        'delivery_title' => 'டெலிவரி {ref}',
        'delivery_not_found' => 'அந்த டெலிவரி இல்லை, அல்லது நீங்கள் பார்க்க முடியாத நிறுவனத்தில் உள்ளது.',
        'delivery_new' => 'புதிய டெலிவரி',
        'order_ref' => 'ஆர்டர் எண்',
        'order' => 'ஆர்டர் {ref}',
        'delivery_n' => 'டெலிவரி #{id}',
        'optional' => 'விருப்பத்தேர்வு',
        'received_date' => 'பெறப்பட்டது',
        'delivery_booked' => '{who} பதிவு செய்தார்',
        'delivery_lines' => 'வரிகள்',
        'delivery_add_line' => 'வரியைச் சேர்',
        'delivery_remove_line' => 'இந்த வரியை அகற்று',
        'delivery_total' => '{n} வரிகள், {value}',
        'delivery_docs_hint' => 'பதிவு செய்த பிறகு, டெலிவரியின் பக்கத்தில் ஆர்டர் உறுதிப்படுத்தல், இன்வாய்ஸ் அல்லது டெலிவரி குறிப்பைச் சேர்க்கவும்.',
        'delivery_undo' => 'டெலிவரியைச் செயல்தவிர்',
        'delivery_undo_line' => 'இந்த வரியைச் செயல்தவிர்க்கவா? மூல பதிவு வரலாற்றில் இருக்கும், அதன் அருகில் செயல்தவிர்ப்பு இருக்கும்.',
        'delivery_undo_what' => 'இந்த டெலிவரியில் ஏற்கனவே செயல்தவிர்க்கப்படாத ஒவ்வொரு வரியையும் செயல்தவிர்க்கவா? மூல பதிவுகள் வரலாற்றில் இருக்கும்.',
        'deliveries_search' => 'ஆர்டர் அல்லது இன்வாய்ஸ் எண், வழங்குநர் அல்லது உருப்படி மூலம் தேடு',
        'deliveries_count' => '{n} டெலிவரிகள்',
        'deliveries_none' => 'இன்னும் டெலிவரிகள் இல்லை. பல உருப்படிகளுக்குப் புதியது, அல்லது ஒரு உருப்படியில் பெறு என்பதைப் பயன்படுத்தவும்.',
        'documents' => 'ஆவணங்கள்',
        'partly_undone' => 'பகுதியாகச் செயல்தவிர்க்கப்பட்டது',
        'h_delivery_created' => 'பதிவு செய்யப்பட்டது',
        'help_p8' => '<strong>டெலிவரிகள்.</strong> ஒரு ஆர்டர் என்பது ஒரு டெலிவரி: <strong>Deliveries → New</strong> வழங்குநர், ஒரு <strong>ஆர்டர் எண்</strong> (விருப்பத்தேர்வு), இன்வாய்ஸ் எண் மற்றும் தேதி, மேலும் ஒவ்வொரு உருப்படிக்கும் ஒரு வரியை எடுத்துக்கொள்கிறது - ஒரே ஆர்டரில் 10 மவுஸ், 10 டோனர், 5 கீபோர்டு. அதைப் பதிவு செய்வது ஒவ்வொரு வரியையும் பெற்றுக்கொள்ளும். டெலிவரியின் பக்கம் அதன் <strong>ஆவணங்களை</strong> (ஆர்டர் உறுதிப்படுத்தல், இன்வாய்ஸ்) வைத்திருக்கும், அதன் விவரங்களைத் திருத்த அனுமதிக்கும் - ஒவ்வொரு மாற்றமும் பதிவாகும் - இரண்டு முறை பதிவு செய்யப்பட்டிருந்தால் <strong>டெலிவரியைச் செயல்தவிர்</strong> செய்யலாம். ஒரு உருப்படியில் ஒரு <strong>பெறு</strong> ஒரு வரி டெலிவரியை உருவாக்குகிறது, எனவே ஒவ்வொரு ரசீதுக்கும் அதன் ஆவணங்களுக்கு ஓர் இடம் உள்ளது.',
        'help_heading' => 'நுகர்பொருட்கள்',
        'help_intro' => '<strong>நுகர்பொருட்கள்</strong> (தலைப்புப் பட்டியில்) என்பவை ஒவ்வொன்றாகக் கண்காணிக்காமல் எண்ணுபவை - டோனர், ஃபியூசர், காகிதம், மவுஸ், கீபோர்டு, RAM. விதி: அதன் வரிசை எண்ணை எழுதி வைப்பீர்கள் என்றால் அது சொத்து; எண்ணுவீர்கள் என்றால் அது நுகர்பொருள். இருப்பு நீங்கள் பணிபுரியும் நிறுவனத்துக்குச் சொந்தமானது.',
        'help_journey' => 'தொடக்கம் முதல் முடிவு வரை, நடக்கும் வரிசையில்:',
        'help_step1' => '1. உங்கள் உருப்படிகளை அமையுங்கள்',
        'help_step2' => '2. எப்போது ஆர்டர் செய்வது என்பதை அறிந்து, ஆர்டர் செய்யுங்கள்',
        'help_step3' => '3. டெலிவரியைப் பெறுங்கள்',
        'help_step4' => '4. பயன்படுத்துங்கள்',
        'help_step5' => '5. தவறுகளைச் சரிசெய்யுங்கள்',
        'help_step6' => '6. அலமாரிகளை எண்ணுங்கள்',
        'help_step7' => '7. எது காணாமல் போனது என்று பாருங்கள்',
        'help_p1' => '<strong>உருப்படிகளும் வகைகளும்.</strong> <strong>புதியது</strong> ஒரு உருப்படியைச் சேர்க்கிறது: அதன் வகை, பாகம் எண், அலகு, வழங்குநர், அலகு விலை, <strong>மறுஆர்டர் அளவு</strong> மற்றும் <strong>குறைந்தபட்சம்</strong>. வகைகள் <strong>Settings → Consumables</strong> இல் அமைக்கப்படுகின்றன, ஒவ்வொரு வகைக்கும் <strong>System → Custom fields → Consumables</strong> இல் சொந்தப் புலங்கள் இருக்கலாம் - டோனருக்கு பக்க விளைச்சல், காகிதத்துக்கு எடை.',
        'help_p2' => '<strong>இருப்பை நகர்த்துதல்.</strong> ஒரு உருப்படியைத் திறந்து, ஒரு டெலிவரியை <strong>பெறு</strong> (அளவு, விலை, வழங்குநர், இன்வாய்ஸ் எண் மற்றும் தேதி - புதிய விலையில் வரும் டெலிவரி அந்த விலையையே புதிய விலையாக்கும்), சிலவற்றை ஒரு நபருக்கு <strong>வழங்கு</strong>, அல்லது ஒரு <strong>திருப்பு</strong> எடுக்கவும். இருப்பு ஒருபோதும் பூஜ்ஜியத்துக்குக் கீழே செல்லாது: இருப்பதை விட அதிகம் வழங்குவது மறுக்கப்படும். <strong>சரிசெய்</strong> (சேதமடைந்த அல்லது கண்டெடுத்த இருப்புக்கு, காரணத்துடன்) System → Roles இல் <em>Adjust consumable stock</em> அனுமதி தேவை.',
        'help_p3' => '<strong>டிக்கெட்டுக்கு எதிராக.</strong> ஒரு டிக்கெட்டில், <strong>Link to... → Consumables</strong> இந்தத் திரையைத் திறக்கும்; ஒவ்வொரு உருப்படியின் அருகிலும் <strong>வழங்கு</strong> இருக்கும், டிக்கெட் மற்றும் அதன் கோரிக்கையாளருடன் நிரப்பப்பட்டிருக்கும். இந்த வழங்கல் டிக்கெட்டின் வரலாற்றிலும் உருப்படியின் வரலாற்றிலும் தோன்றும்.',
        'help_p9' => '<strong>நுகர்பொருட்களைப் பயன்படுத்துதல்.</strong> பட்டியலில் ஒரு டிக்கெட்டை வலது-சொடுக்கி <strong>Use a consumable</strong> என்பதைத் தேர்ந்தெடுக்கவும்: டிக்கெட்டின் நிறுவனத்தின் முதல் 10 உருப்படிகள், எத்தனை இருப்பில் உள்ளன என்பதுடன், ஒரு தேடல் பெட்டியும் காட்டப்படும். ஒன்றைத் தேர்ந்தெடுத்தால் டிக்கெட்டுக்கு எதிராக, அதன் கோரிக்கையாளருக்கு, ஒன்று வழங்கப்படும். டிக்கெட்டின் <strong>Links</strong> எது பயன்படுத்தப்பட்டது என்பதைக் காட்டும் - குறுக்கு அடையாளம் காரணத்துடன் அதைச் செயல்தவிர்க்கும். ஒரு கோரிக்கைப் படிவம் <strong>எந்த</strong> நுகர்பொருள் என்று கேட்கலாம்: Forms இல் <strong>Consumables</strong> மீது ஒரு <strong>Lookup</strong> கேள்வியைச் சேர்க்கவும் (போர்டலிலும் இதைப் பயன்படுத்தலாம்). அதிலிருந்து எழுப்பப்படும் டிக்கெட் கேட்கப்பட்ட உருப்படியை உடைந்த கோட்டுப் பில்லாகக் காட்டும் - ஒன்றைப் பயன்படுத்த அதைச் சொடுக்கவும். கேட்பது இருப்பை ஒருபோதும் நகர்த்தாது; பயன்படுத்துவது மட்டுமே நகர்த்தும்.',
        'help_p4' => '<strong>எல்லாம் பதிவு செய்யப்படுகிறது.</strong> யாரும் இருப்பு எண்ணைத் தட்டச்சு செய்வதில்லை - ஒவ்வொரு ரசீது, வழங்கல், திருப்பல் மற்றும் சரிசெய்தலும் உருப்படியின் <strong>இயக்கங்களில்</strong> ஒரு வரியாகும், யார், எப்போது, யாருக்கு, டிக்கெட் மற்றும் அப்போதைய மதிப்புடன். ஒரு தவறு <strong>செயல்தவிர்</strong> மற்றும் ஒரு காரணத்தால் சரிசெய்யப்படுகிறது: மூல பதிவு இருக்கும், அதன் அருகில் செயல்தவிர்ப்பு இருக்கும். உருப்படியில் செய்யும் மாற்றங்கள் அதன் <strong>வரலாறு</strong> தாவலில் இருக்கும்.',
        'help_p5' => '<strong>குறைந்து வருதல்.</strong> <strong>மறுஆர்டர் அளவில்</strong> அல்லது அதற்குக் கீழே ஒரு உருப்படி <em>குறைவு</em> எனக் குறிக்கப்படும், Watchtower-இல் <em>குறைந்த இருப்பு</em> கீழ் எண்ணப்படும், Settings → Consumables இல் தேர்ந்தெடுக்கப்பட்டவர்களுக்கு - ஒவ்வொரு முறை குறையும்போதும் ஒரு முறை - பெல் அறிவிப்பு கிடைக்கும். <strong>மறுஆர்டர்</strong> அங்கு தேர்ந்தெடுத்த கொள்முதல் கோரிக்கைப் படிவத்தைத் திறக்கும்; உருப்படி, அதன் வழங்குநர் மற்றும் பரிந்துரைக்கப்பட்ட அளவுடன் நிரப்பப்பட்டிருக்கும், அது அந்தப் படிவத்தின் ஒப்புதல்கள் வழியாகச் செல்லும்.',
        'help_p6' => '<strong>இருப்பு சரிபார்ப்பு.</strong> ஒன்றைத் தொடங்கி, அலமாரிகளைப் பார்த்து உண்மையில் இருப்பதைத் தட்டச்சு செய்யுங்கள். ஒவ்வொரு வரியும் அந்த நேரத்தில் பதிவுகள் எதிர்பார்த்தது, எண்ணப்பட்டது, வேறுபாடு மற்றும் அதன் மதிப்பை வைத்திருக்கும் - 10 எதிர்பார்த்து 8 கண்டால் -2 எனப் பதிவாகும். <strong>முடி</strong> இருப்பைச் சரிசெய்யும், <em>Adjust consumable stock</em> அனுமதி தேவை; <strong>ரத்து</strong> எதையும் மாற்றாது.',
        'help_p7' => '<strong>வேறுபாடுகள்</strong> இருப்பு சரிபார்ப்புகளில் குறைவாகவோ கூடுதலாகவோ கண்டறியப்பட்டவற்றை, மாதம் வாரியாக, பணத்திலோ அலகுகளிலோ, மேலும் அதிகம் காணாமல் போகும் உருப்படிகளைக் காட்டுகிறது. குறைவும் கூடுதலும் தனித்தனியாகக் காட்டப்படுகின்றன, எனவே ஒன்று மற்றொன்றை மறைக்காது.',
    ],
];
